        setValue(L.MSG_STYLE_PREVIEW_SAMPLE, "# 제1장\n\n*비*는 **사흘째** 그치지 않았고, 항구로 가는 길은 진흙 강이 되어 있었다. \"돌아가야 해요.\" 마라가 말했지만 아무도 움직이지 않았다.\n\n> 오래된 지도는 틀렸다. 물을 믿어라.\n\n---\n\n아침은 잿빛으로 느리게 왔다. 그녀는 부두를 따라 늘어선 등불을 세었다. `일곱 개`. 그리고 걷기 시작했다.\n\n## 작은 제목\n\n이 문단의 줄은 텍스트가 어떻게 줄 바꿈되고 정렬되는지, 그리고 하이픈 넣기가 켜져 있으면 어떻게 단어가 나뉘는지 보여 줄 만큼 충분히 깁니다. 아주 긴 단어도 마찬가지입니다.");
