        setValue(L.HELP_ASSISTANT_ADMIN_DATA, "관리자가 요청하면 어시스턴트가 관리 페이지의 데이터를 읽을 수 있습니다: 확장 기능의 상태와 로그, 데이터베이스 백업, 정리가 제거할 내용, 사용자 수(이름 제외). 이 정보는 어시스턴트의 모델로 전송되며, 외부 제공자일 수 있고 로그에는 확장 기능이 쓴 텍스트가 포함될 수 있습니다. 다른 사용자에게는 허용되지 않습니다. 아무것도 변경할 수 없습니다.");
        setValue(L.HELP_COMMAND_TYPE_SLASH, "/와 명령 이름을 입력하세요. 인수는 공백으로 구분합니다. 인수에 속한 공백이나 백슬래시 앞에는 \\를 붙이거나 인수를 \"큰따옴표\"로 감싸세요.");
        setValue(L.HELP_COMMAND_NO_MATCH, "일치하는 명령이 없습니다.");
        setValue(L.HELP_COMMAND_TOO_MANY_ARGUMENTS, "명령이 받는 것보다 인수가 많습니다.");
        setValue(L.HELP_COMMAND_DESTRUCTIVE, "이 명령은 존재하는 데이터를 변경하거나 제거합니다.");
        setValue(L.HELP_COMMAND_NON_DESTRUCTIVE, "이 명령은 데이터를 읽거나 새 데이터를 추가하기만 하며, 존재하는 것은 변경하지 않습니다.");
        setValue(L.HELP_AGENTS_MAX_AGENTS, "복제본을 포함해 사용자가 가질 수 있는 에이전트 수. 비워 두면 5개이며, 0이면 기존 에이전트는 유지하고 실행할 수 있지만 새로 만들거나 복제할 수 없습니다.");
        setValue(L.HELP_AGENTS_MAX_CONCURRENT_RUNS, "사용자의 실행을 동시에 몇 개까지 작업할 수 있는지. 비워 두면 1개.");
        setValue(L.HELP_AGENTS_RUN_TOKEN_BUDGET, "사용자의 실행 한 번이 쓸 수 있는 최대 토큰 수(전송 및 생성). 비우거나 0이면 제한 없음.");
        setValue(L.HELP_AGENT_SYSTEM_PROMPT, "지시문 앞에서 에이전트에게 알려 주는 역할. 비워 두면 기본값(설정의 내 기본값, 없으면 관리자의 것, 없으면 내장된 것)을 따르며 이것이 플레이스홀더입니다. 정보 아이콘이 이를 채워 주어 사본을 편집할 수 있습니다.");
        setValue(L.HELP_AGENT_INSTRUCTIONS, "에이전트에 대한 지시문으로, 실행할 때마다 프롬프트에 추가됩니다. 에이전트는 읽을 수만 있고 변경할 수 없습니다. 비워 두면 설정의 기본 지시문을 사용합니다.");
        setValue(L.HELP_AGENT_DESTRUCTIVE, "에이전트가 데이터를 변경하거나 제거하는 명령을 실행하려 할 때의 동작.");
        setValue(L.HELP_AGENT_MAX_ROUNDS, "한 번의 실행에서 모델에 보낼 수 있는 최대 요청 수. 비워 두면 에이전트 자체의 제한이 없습니다.");
        setValue(L.HELP_AGENT_TOKEN_BUDGET, "한 번의 실행이 쓸 수 있는 최대 토큰 수. 비우거나 0이면 에이전트 자체의 제한이 없으며, 관리자가 부여한 제한은 그대로 적용됩니다.");
        setValue(L.HELP_AGENT_CONTEXT_LIMIT, "모델의 컨텍스트 제한(토큰), 모델 자체의 컨텍스트보다 낮게 설정합니다. 이에 가까워지면 오래된 라운드가 요약됩니다. 비워 두면 모델의 컨텍스트입니다.");
        setValue(L.HELP_AGENT_SEES_IMAGES, "모델이 이미지를 받으면 선택하세요. 그러면 에이전트가 작업 공간의 이미지를 보여 주는 도구를 받습니다 (업로드로 거기에 넣습니다). 로어 생성기처럼 자체 모델에 이미지를 보내는 명령은 이 설정과 관계없이 작업 공간의 이미지를 사용합니다.");
        setValue(L.HELP_AGENT_MESSAGE_QUEUED, "에이전트가 작업 중입니다. 에이전트가 읽을 준비가 될 때까지 메시지가 대기합니다.");
        setValue(L.HELP_AGENT_SEND_NOW, "에이전트가 이번 라운드에서 하던 작업을 버리고 메시지를 바로 보냅니다.");
        setValue(L.HELP_AGENT_DEFAULT_PROMPT_USER, "자체 시스템 프롬프트가 없는 내 에이전트가 사용합니다. 비워 두면 관리자의 기본값, 없으면 내장 프롬프트를 따릅니다.");
        setValue(L.HELP_AGENT_DEFAULT_PROMPT_APP, "자체 시스템 프롬프트가 없고 사용자가 설정에 기본 프롬프트를 두지 않은 에이전트가 사용합니다. 비워 두면 내장 프롬프트입니다.");
        setValue(L.HELP_AGENTS_MAX_FILE_KB, "사용자의 에이전트가 쓸 수 있는 가장 큰 파일(KB). 비워 두면 1024(1MB).");
        setValue(L.HELP_AGENTS_MAX_WORKSPACE_MB, "한 에이전트의 작업 공간에 있는 모든 파일이 차지할 수 있는 용량(MB). 비워 두면 20.");
        setValue(L.HELP_AGENTS_MAX_WORKSPACE_FILES, "한 에이전트의 작업 공간에 담을 수 있는 파일 수 (폴더는 제외). 비워 두면 500.");
        setValue(L.HELP_AGENTS_MAX_COPIES, "사용자의 실행이 동시에 유지할 수 있는 책 작업 사본의 수. 끝나지 않은 실행(일시 정지 포함)은 사본을 유지합니다. 비우거나 0이면 에이전트 수 외에는 제한이 없습니다.");
        setValue(L.HELP_AGENT_COMPACTION_PROMPT, "에이전트의 작업을 압축할 때(콘솔의 /compact) 에이전트에게 요청하는 내용: 이전 라운드를 대체하는 요약을 작성합니다. 비워 두면 기본값(설정의 내 기본값, 없으면 관리자의 것, 없으면 내장된 것)을 따르며 이것이 플레이스홀더입니다. 정보 아이콘이 이를 채워 주어 사본을 편집할 수 있습니다.");
        setValue(L.HELP_AGENT_DEFAULT_COMPACTION_PROMPT_USER, "자체 압축 프롬프트가 없는 내 에이전트가 사용합니다. 비워 두면 관리자의 기본값, 없으면 내장 프롬프트를 따릅니다.");
        setValue(L.HELP_AGENT_DEFAULT_COMPACTION_PROMPT_APP, "자체 압축 프롬프트가 없고 사용자가 설정에 기본값을 두지 않은 에이전트가 사용합니다. 비워 두면 내장 프롬프트입니다.");
        setValue(L.HELP_AGENT_COMMAND, "명령은 에이전트가 아니라 사용자가 실행하며, 에이전트는 사용자가 실행했다는 사실과 결과를 전달받습니다. 에이전트가 작업하는 동안 명령은 그 턴이 끝날 때까지 대기합니다.");
        setValue(L.HELP_AGENT_RUN_NOW, "에이전트가 이번 라운드에서 하던 작업을 버리고 명령을 바로 실행합니다.");
        setValue(L.HELP_AGENTS_MAX_CHECKPOINT_MB, "한 번의 실행에서 모든 체크포인트가 차지할 수 있는 용량(MB). 작업 사본과 작업 공간의 복원 지점으로, 에이전트가 만든 것과 자동으로 만들어진 것이 포함됩니다. 비워 두면 100.");
        setValue(L.HELP_AGENT_CHECKPOINTS, "책의 작업 사본과 작업 공간의 복원 지점입니다. 실행은 시작할 때 하나, 무언가를 변경하는 라운드 전에 하나씩 만듭니다 (마지막 5개 유지). 에이전트도 자체 체크포인트를 저장할 수 있습니다. 이들은 관리자가 정한 할당량을 공유합니다. 복원은 책과 작업 공간을 되돌리고, 되감기는 대화도 체크포인트를 만든 시점으로 되돌려 에이전트가 책에 더 이상 없는 작업을 기억하지 않게 합니다 (일시 정지되거나 중지된 실행).");
        setValue(L.HELP_MERGE, "에이전트는 책의 사본에서 작업했습니다. 반영할 내용을 선택하세요. 책은 먼저 저장됩니다. 오른쪽의 텍스트가 기록될 내용이며 편집하여 바꿀 수 있습니다. 충돌은 사용자와 에이전트가 모두 바꾼 텍스트입니다.");
        setValue(L.HELP_COMMAND_PRESETS, "역할: 감사자는 읽기만 하고, 로어 관리자는 로어북도 쓰며, 편집자는 텍스트, 요약, 책 정보도 수정하고, 초안 작성자는 새 파트를 추가하고 모델이 다음 턴을 쓰게 합니다. 누구도 데이터를 제거할 수 없습니다.");
        setValue(L.HELP_AGENT_PAUSE_NOW, "진행 중인 모델 요청과 호출을 취소하고 즉시 일시 정지합니다. 그것들이 하려던 작업은 사라지며, 멈출 수 없는 호출은 그래도 끝날 수 있고 에이전트는 계속할 때 상태를 확인합니다.");
        setValue(L.HELP_AGENT_DEFAULT_INSTRUCTIONS_USER, "자체 지시문이 없는 내 에이전트에 대한 지시문으로, 실행할 때마다 프롬프트에 추가됩니다. 비워 두면 지시문이 없습니다.");
        setValue(L.HELP_AGENT_AUTO_COMPACT, "모델의 컨텍스트가 제한의 이 비율을 넘고 에이전트가 스스로 작업을 압축하지 않았다면, 실행이 이전 라운드를 요약합니다. 비워 두면 %d입니다. 0은 압축하지 않으며 (그러면 컨텍스트가 가득 찼을 때 실행이 멈춥니다), 그 외에는 %d에서 99 사이입니다.");
        setValue(L.HELP_AGENT_USE_OWN_MODEL, "켜면: 에이전트가 명령으로 쓴 것(다음 턴, 요약, 로어 생성기 같은 확장 기능의 명령)이 책의 모델과 관계없이 위의 모델을 사용합니다. 끄면: 책의 모델을 사용하므로 모델을 섞을 수 있습니다: 생각하는 모델과 쓰는 모델. 명령이 에이전트의 다른 모델 프로필을 지정할 수도 있습니다.");
        setValue(L.HELP_AGENT_WEBHOOK_URL, "에이전트가 무언가를 묻거나, 사용자를 기다리거나, 끝나거나, 실패했는데 애플리케이션이 열려 있지 않으면 서버가 이 주소로 짧은 메시지를 보냅니다: 예를 들어 ntfy 토픽(https://ntfy.sh/your-topic), Gotify 메시지 URL, Discord 웹훅. 주소를 아는 사람은 누구나 메시지를 읽을 수 있습니다. 비워 두면 아무것도 보내지 않습니다.");
        setValue(L.HELP_AGENT_WEBHOOKS_ALLOWED, "서버가 사용자가 설정에 입력한 주소를 호출합니다. 허용할 수 없는 환경(예: 서버가 사용자가 접근해서는 안 되는 네트워크에 닿을 수 있는 경우)에서는 끄세요.");
        setValue(L.HELP_AGENTS_MAX_CONCURRENCY, "한 번의 실행이 에이전트와 하위 에이전트를 합쳐 동시에 진행 중으로 둘 수 있는 모델 요청 수. 1이면 하위 에이전트가 모델에 요청하는 동안 에이전트가 대기(보류)합니다. 비워 두면 1.");
        setValue(L.HELP_AGENT_MAX_SUBAGENTS, "에이전트가 동시에 작업시킬 수 있는 하위 에이전트 수. 0이거나 비워 두면 없음: 에이전트가 하위 에이전트를 시작하는 도구를 받지 않습니다. 1이면 하위 에이전트를 시작할 때 끝날 때까지 기다리고, 더 많으면 제한에 도달할 때까지 호출이 즉시 반환되며 그 후에는 하나가 끝나기를 기다립니다. 하위 에이전트는 하위 에이전트를 시작할 수 없으며, 모두의 요청이 실행의 예산에 포함됩니다.");
        setValue(L.HELP_AGENT_CANCEL_QUEUED, "메시지나 명령을 취소합니다: 에이전트는 이를 받지 않습니다.");
        setValue(L.HELP_AGENT_CONTEXT, "모델이 다음 요청에서 읽는 내용을 부분별로 보여 줍니다: 시스템 메시지, 도구 정의, 대화. 잘린 것은 없으며, Markdown으로 다운로드해 편집기에서 읽을 수 있습니다. 각 부분의 토큰 수는 추정치이고, 차트의 선은 모델이 보고한 값입니다.");
        setValue(L.HELP_AGENT_ROLLBACK_MESSAGE, "대화를 이 메시지 이전으로 되돌립니다: 에이전트는 이 메시지와 그 이후를 모두 잊고, 작업 사본과 작업 공간은 그 직전의 가장 가까운 체크포인트로 돌아갑니다.");
        setValue(L.HELP_AGENT_COPY, "에이전트가 작업하는 책의 사본을 읽기용으로 보여 줍니다: 여기서는 아무것도 변경되지 않습니다. 이야기는 분기별로, 로어북은 항목과 함께 표시됩니다. 이 탭을 표시하거나 새로 고침을 누를 때 읽습니다.");
        setValue(L.HELP_AGENT_SUBAGENTS, "실행의 하위 에이전트가 받은 지시, 말한 것, 호출한 것, 끝난 방식을 보여 줍니다. 실행 중에는 그 진행을 따라가며, 이전 실행의 것은 실행 목록에서 해당 실행을 선택해 읽습니다.");
        setValue(L.HELP_AGENT_COMMAND_TOKENS, "명령의 정의(이름, 설명, 매개변수)가 에이전트의 모든 요청에 더하는 양의 추정치입니다. 명령을 적게 선택할수록 작업을 위한 공간이 더 남습니다.");
        setValue(L.HELP_MULTI_TAG, "태그를 선택(또는 새로 입력)한 다음 항목별로, 또는 아래에서 선택한 모든 항목에 적용하거나 제거하세요. 태그가 있는 항목이 먼저 나열되고 표시됩니다. 에이전트가 작업 중인 항목은 회색으로 표시되며 변경할 수 없습니다.");
        setValue(L.HELP_AGENT_DIAGNOSTICS, "실행이 한 일을 기록에서 집계합니다: 도구별 호출과 그 오류, 결과, 시간, 도구를 연이어 호출하는 데 쓴 라운드, 가장 큰 결과, 가장 느린 라운드, 컨텍스트, 하위 에이전트. 오래된 실행도 포함해 모든 실행에서 작동합니다. Markdown이나 JSON으로 다운로드하여 편집기에서 읽거나 다른 사람에게 전달할 수 있습니다.");
        setValue(L.HELP_COMMAND_BATCH_POLICY, "한 번의 응답 안의 호출 중에서 명령이 사용되는 방식. 함께: 다른 호출과 함께 호출될 수 있음. 단독: 길거나 비용이 많이 들거나(예: 모델 호출을 함) 결과를 먼저 읽어야 하므로 자체 응답에서 호출됨. 에이전트가 이를 무시하도록 설정할 수 있습니다.");
        setValue(L.HELP_AGENT_BATCH_MODE, "에이전트의 한 응답에서 몇 개의 호출을 실행하는지. 모두 함께: 명령의 일괄 정책과 관계없이 모든 호출 (가장 빠름). 함께, 단독으로 표시된 명령은 따로: 호출은 함께 실행되지만 단독으로 표시된 명령은 자체 응답에서 실행됨. 응답당 호출 하나: 첫 호출만 실행되고 에이전트가 결과를 읽은 후 다음 호출을 작성함 (가장 느림, 모든 호출이 모델의 생각이 포함된 라운드이지만 각 결과에 반응할 수 있음). 오류는 모든 모드에서 응답을 끝냅니다: 실패한 호출 이후의 호출은 실행되지 않습니다.");
        setValue(L.HELP_LOREBOOK_MASS_EDIT, "로어북과 그 하위 책의 모든 항목을 순서대로 보여 줍니다. 항목의 사용 체크박스, 이름, 순서, 태그를 그 자리에서 바꿀 수 있으며, 텍스트는 줄여서 표시됩니다 (읽거나 편집하려면 로어북에서 항목을 여세요). 행의 로어북 상자로 항목을 로어북 자체나 하위 책으로 이동하거나, 아래의 상자로 선택한 모든 항목을 한꺼번에 이동하세요. 에이전트가 작업 중인 로어북의 항목은 회색으로 표시되며 변경할 수 없습니다.");
        setValue(L.HELP_STORY_PARTS_LIMIT, "이야기와 리더는 책의 파트를 이 개수만큼만 불러 둡니다: 이야기는 마지막 파트부터, 리더는 이 브라우저에서 마지막으로 읽던 위치(또는 처음)부터 시작합니다. 앞뒤 파트는 스크롤하면 불러오고, 현재 위치에서 먼 파트는 다시 해제됩니다. 비워 두면 모든 파트를 한꺼번에 불러옵니다.");
        setValue(L.HELP_AGENT_MODELS, "에이전트가 하위 에이전트를 시작할 수 있는 다른 모델: spawn_agent의 프로필로 역할과 설명을 읽고 하나를 선택합니다. 각 모델의 명령은 에이전트가 허용된 것 이하입니다.");
        setValue(L.HELP_AGENT_SELF_SUBAGENT, "끄면: 에이전트는 목록의 다른 모델에서만 하위 에이전트를 시작할 수 있습니다. 다른 모델이 없으면 에이전트는 하위 에이전트용 도구를 받지 않습니다.");
        setValue(L.HELP_AGENT_MODEL_COMMANDS, "끄면: 이 모델의 하위 에이전트는 에이전트의 명령을 가집니다. 켜면: 선택한 명령만, 그리고 그중 에이전트가 허용된 것만 가집니다. 파일 도구는 명령이 아니며 하위 에이전트는 항상 가집니다.");
        setValue(L.HELP_AGENT_MODEL_TOOLS, "끄면: 모델은 텍스트로만 응답하며 명령도 도구도 받지 않습니다.");
        setValue(L.HELP_AGENT_RESUME_NOTE, "에이전트는 계속할 때 이것을 먼저 읽으며, 사용자가 책을 변경한 내용이 있으면 그 보고서 뒤에 읽습니다. 사용자의 메시지를 기다리지 않는 실행에도 적용됩니다.");
        setValue(L.HELP_AGENT_LANGUAGE, "에이전트가 읽는 모든 것의 언어: 명령의 설명, 결과, 오류. 책의 언어와는 관계없습니다: 에이전트는 설정과 관계없이 책의 언어로 책을 씁니다. 명령과 그 매개변수는 모든 언어에서 영어이므로, 특히 작은 모델에는 영어가 가장 안정적입니다. 목록에는 설치된 언어가 표시되며, 실행은 시작할 때의 언어를 유지합니다.");
        setValue(L.HELP_JSON_MERGE, "에이전트의 데이터, 현재 책의 데이터, 실행 시작 시점의 데이터를 겹쳐 보여 줍니다. 위치를 선택하고 그중 하나의 데이터를 가져오거나, 제외하거나, 그 안에서 조합할 수 있습니다. 한쪽만 바꾼 것은 그쪽에서 가져오고, 양쪽이 바꾼 것은 위치별로 합쳐지며, 양쪽이 같은 방식으로 바꾼 위치는 충돌이고 결정하기 전까지 에이전트의 버전이 사용됩니다. 위치를 열면 그것만 다룰 수 있습니다. 목록의 요소는 그 정체(같은 데이터, 같은 ID나 이름, 비슷해 보이는 것)로 짝지어지며, 추측이 틀리면 요소를 분할하거나 다른 요소와 짝지으세요. 텍스트 보기에서는 열린 위치의 에이전트 데이터를 직접 쓸 수 있으며, 트리로 돌아갈 때 검사됩니다.");
        setValue(L.HELP_NOTIFICATIONS_ALLOW_LOCAL, "권한이 부여된 경우에만 해당합니다. 그러면 서버가 localhost, 접근 가능한 사설 네트워크, 링크 로컬 주소(예: 내 네트워크의 ntfy나 Gotify)로도 메시지를 보냅니다. 권한이 없으면 공개 주소만 호출합니다. 관리자는 제한되지 않습니다.");
        setValue(L.HELP_COMMAND_SEARCH, "명령의 이름이나 설명에 있는 단어를 순서에 관계없이 입력하세요. 표에는 모든 단어를 가진 명령만 표시되며, 위의 선택은 여전히 모든 명령에 적용됩니다.");
        setValue(L.HELP_KEYBOARD_SHORTCUTS, "기록을 클릭하고 새 키 조합을 누르세요. Ctrl, Alt, Meta 없는 키는 텍스트 필드에 포커스가 없을 때만 작동합니다. 단축키는 열린 책의 이야기 탭에서 작동합니다.");
        setValue(L.HELP_ST_MERGE_TURNS, "사용자의 메시지가 그 뒤에 오는 응답으로 만든 파트의 지시문이 됩니다. 이 설정이 없으면 모든 메시지가 별개의 파트가 됩니다.");
        setValue(L.HELP_AI_TOKENIZER, "이 AI의 토큰을 세는 방법. 자동은 서버의 토크나이저 엔드포인트(OpenAI, llama.cpp, LiteLLM)를 시도하고 로컬 추정으로 대체합니다. 하나를 선택하면 그것만 사용합니다. 플러그인의 토크나이저는 여기서 선택된 경우에만 엔드포인트, 모델, 텍스트를 받습니다.");
        setValue(L.HELP_SCAN_DEPTH, "사용된 항목의 내용에서 다른 항목의 필터를 몇 번 검색하는지 (0 = 검색하지 않음). 이 로어북과 자체 스캔 깊이가 없는 하위 로어북에 적용됩니다.");
        setValue(L.HELP_PREVENT_RECURSION, "이 항목의 내용에 있는 단어는 다른 항목을 활성화하지 않습니다.");
        setValue(L.HELP_ACTIVATION_PREVIEW, "이 텍스트의 턴에서 이 로어북과 하위 책의 어떤 항목이 사용되는지, 그리고 그 이유를 이 로어북의 스캔 깊이로 보여 줍니다. 실제 생성에서는 확장 기능이 결과를 바꿀 수 있습니다. 이야기의 파트도 살펴보는 항목은 선택한 책의 최신 파트를 사용합니다.");
        setValue(L.HELP_ACTIVATION_CONTEXT, "필터를 찾는 위치: 턴의 지시문에서만, 또는 지시문과 이야기의 최신 파트에서.");
        setValue(L.HELP_ACTIVATION_PARTS, "지시문과 함께 검색할 이야기의 최신 파트 수 (최소 1).");
        setValue(L.HELP_PART_SYSTEM_PROMPT, "시스템 메시지입니다. 파트 앞의 이야기는 대화의 이전 메시지로 그 뒤에 전송되므로, 요청마다 같은 내용만 여기에 두세요. 그러면 서버가 이미 읽은 내용을 재사용할 수 있습니다.");
        setValue(L.HELP_PART_LAST_PROMPT, "사용자의 마지막 메시지: 요청마다 바뀌는 내용 (파트 뒤의 이야기, 파트 자체, 파트의 메모, 작업).");
        setValue(L.HELP_MASS_CHANGE_MODEL_PROTOCOL, "책에 적용할 모델 및/또는 프로토콜을 선택하고 책을 체크하세요. 선택하지 않으면 \"바꾸지 않음\"이며, 책의 해당 부분은 그대로 유지됩니다. 에이전트가 작업 중인 책은 회색으로 표시되며 변경할 수 없습니다.");
        setValue(L.HELP_MASS_CHANGE_LANGUAGE, "책에 적용할 언어를 선택하고 책을 체크하세요. 에이전트가 작업 중인 책은 회색으로 표시되며 변경할 수 없습니다.");
        setValue(L.HELP_ORGANISE, "왼쪽 / 오른쪽 / Tab: 다른 창. Enter: 폴더 열기. Backspace: 위로. Space 또는 Insert: 표시. 버튼의 키는 설정(키 바인딩)에서 바꿀 수 있습니다.");
        setValue(L.HELP_FOLDER_SETTINGS, "이 폴더와 그 아래 폴더의 책은 자체 설정이 없는 한 이 설정을 사용합니다. 비어 있는 필드는 상위 폴더에서, 그다음 내 설정에서 상속됩니다.");
        setValue(L.HELP_MASS_RENAME, "책의 이름을 바꾸는 방법을 선택하고 책을 체크하세요: 새 이름 열에 결과가 표시됩니다. 번호 매기기는 체크한 책을 목록 순서대로 셉니다. 패턴에서 {name}은 현재 이름이고 {n}은 번호입니다. 에이전트가 작업 중인 책은 회색으로 표시되며 이름을 바꿀 수 없습니다.");
        setValue(L.HELP_HISTORY_MAX_VERSIONS, "기록이 한 파트에 대해 보관하는 버전 수 (휴지통의 것 포함). 비워 두면 이 수준에서는 제한이 없습니다. 0이면 기록을 보관하지 않습니다. 책, 폴더, 내 설정, 관리자의 제한 중 가장 엄격한 것이 적용됩니다. 처음 생성된 버전과 저장한 버전은 별도로 유지됩니다.");
        setValue(L.HELP_VERSION_HISTORY_PERMISSION, "사용자 책의 기록이 한 파트에 대해 보관하는 최대 버전 수. 비워 두면 관리자의 제한이 없습니다. 이 권한이 없는 사용자는 50개이며, 부여되지 않은 권한은 기록을 보관하지 않습니다.");
        setValue(L.HELP_DAILY_GOAL, "모든 책에 걸친 통계 달력의 목표: 하루에 직접 쓴 단어(생성된 것 제외)와 편집한 시간(분). 설정된 모든 목표에 도달한 날은 목표 연속 일수에 포함됩니다. 비워 두면 목표가 없습니다.");
        setValue(L.HELP_ACTIVATION_RANGE, "항목은 이 번호부터 이 번호까지의 파트를 만드는 턴에만 사용됩니다 (이야기 개요의 번호이며 양쪽 포함, 첫 파트는 1). 제한이 없으려면 필드를 비워 두세요. 스와이프나 재생성은 교체하는 파트로 셉니다. 책 없이 미리 보는 턴은 번호가 없으므로 범위를 확인하지 않습니다.");
        setValue(L.HELP_STYLES, "스타일은 이야기와 리더에서 파트의 텍스트가 보이는 방식을 바꿉니다. 내장 스타일은 변경할 수 없습니다: 복제하여 나만의 스타일을 만드세요. 기본 스타일은 이야기의 스타일 변경 메뉴에서 스타일을 고르지 않은 책이 사용합니다.");
        setValue(L.HELP_STYLE_VALUES, "모든 CSS 값 (예: 1.1rem, #336699, var(--lumo-body-text-color)). 비워 두면 애플리케이션의 모양을 유지합니다.");
        setValue(L.HELP_STYLE_CUSTOM_CSS, "옵션 뒤에 스타일의 범위 안에서 추가되는 CSS입니다. 파트의 텍스트에 대한 규칙(예: \".chat-message-markdown p { text-indent: 1.5em !important; }\") 또는 요소 전체에 적용되는 선언을 쓰세요.");
        setValue(L.HELP_EXPORT_SETTINGS, "각 형식은 여기서 선택한 스타일과, 내보내기 대화 상자에서 다르게 선택하기 전까지는 내 버전의 템플릿으로 내보내집니다. 내보내기용 스타일은 스타일 탭에서 만듭니다 (\"내보내기용\" 체크). 템플릿을 비워 두면 기본 템플릿을 사용합니다.");
        setValue(L.HELP_IMAGE_LAYOUT, "뷰어와 내보내기는 이미지를 이렇게 배치합니다. 이야기 편집기는 이미지를 텍스트 뒤에 나열하며, \"뷰어와 같은 방식으로 미리 보기\"가 결과를 보여 줍니다.");
        setValue(L.HELP_LOREBOOK_SHARED, "다른 사용자는 \"다른 사용자에게서 가져오기\"에서 이 로어북과 공유된 하위 로어북을 보고 사본을 가져올 수 있습니다. 내 것을 변경할 수는 없습니다.");
        setValue(L.HELP_PROTOCOL_SHARED, "다른 사용자는 \"다른 사용자에게서 가져오기\"에서 이 프로토콜을 보고 사본을 가져올 수 있습니다. 내 것을 변경할 수는 없습니다.");
        setValue(L.HELP_MATCH_BY_POSITION, "요약은 파트의 ID로 파트와 짝지어집니다. 다른 책의 파일(사본은 ID가 다릅니다)이면 이것을 체크하세요: 파트가 이 분기에 없는 요약은 같은 위치의 요약으로 이동합니다.");
        setValue(L.HELP_ANNOTATE_INSTRUCTIONS, "모델이 파트에 주석을 달 때 찾는 것, 예: 연속성 오류, 약한 대화를 표시. 비워 두면 주석 프롬프트의 기본 작업입니다. AI로 주석 달기 창은 이 텍스트로 시작합니다.");
        setValue(L.HELP_ACTIVATION_CONDITION, "내용과 같은 방식(매크로와 Handlebars)으로 작성하는 템플릿으로, 시점, 등장인물, 지시문, 변수와 함께 턴에 대해 렌더링됩니다. 결과가 참일 때만 항목이 사용됩니다: 빈 값, 0, false, no, off를 제외한 모든 것. 렌더링할 수 없는 조건(오류, 존재하지 않는 이름, 시간 초과)은 거짓으로 처리되며 활성화 미리 보기가 이유를 알려 줍니다. 필터보다 먼저, 다른 항목의 내용으로 찾은 항목에 대해서도 확인합니다. 읽기만 하는 명령은 사용할 수 있고 변수는 변경되지 않습니다. 비워 두면 조건이 없습니다.");
        setValue(L.HELP_REASONING_PASSTHROUGH, "모델의 생각이 다음 요청에서 모델에 다시 전달되는지 여부 (reasoning_content로). 도구 호출 사이: Gemma 4가 기대하는 대로 한 응답의 도구 호출이 이어지는 동안에만. 항상: 생각이 있는 모든 이전 응답과 함께. 대부분의 모델과 서버는 없음을 원합니다.");
        setValue(L.HELP_RECURSION_ONLY, "항목은 턴의 지시문이나 이야기 때문에 사용되지 않습니다. 사용된 다른 항목의 내용에서 필터가 발견될 때만 사용됩니다 (스캔 깊이가 0보다 크고 필터가 필요합니다).");
        setValue(L.HELP_ACTIVATION_SUMMARIES, "필터는 지금까지의 이야기 요약(프롬프트가 사용할 것)에서도 찾습니다.");
        setValue(L.HELP_OWN_SCAN_DEPTH, "이 로어북이 다른 로어북의 하위 로어북일 때 이 로어북 항목의 스캔 깊이 (0 = 다른 항목의 내용으로 절대 찾지 않음). 비워 두면 책이 사용하는 로어북의 스캔 깊이입니다.");
        setValue(L.HELP_AUTHORSHIP, "현재 분기의 모든 파트 기록에서 계산합니다: 모델이나 에이전트가 쓴 단어와 직접 입력하거나 변경한 단어. 모든 버전을 읽으므로 긴 책에서는 시간이 걸립니다.");
        setValue(L.HELP_INCLUDE_AUTHORSHIP, "내보낸 텍스트 끝에 직접 쓴 단어 수와 모델이 생성한 단어 수를 밝히는 문구를 추가합니다. 문구는 내보내기 설정의 템플릿입니다.");
        setValue(L.HELP_STATISTICS_RECORD, "끄면 내 책에 대한 새 집계, 시간, 크기가 기록되지 않습니다. 이미 기록된 것은 지울 때까지 남습니다. 관리자가 모든 사용자의 기록을 꺼 두었을 수 있습니다.");
        setValue(L.HELP_STATISTICS_KEEP_MONTHS, "오래된 날짜는 하루에 한 번 영구 삭제됩니다. 0이면 모두 보관합니다. 관리자가 더 적게 보관할 수 있습니다.");
        setValue(L.HELP_STATISTICS_ADMIN, "통계는 사용자가 책을 작업한 시점, 시간, 책의 이름과 폴더(삭제된 책 포함)를 보관합니다. 기록을 끄거나 보관 기간을 제한하세요. 사용자는 자신에게 더 짧은 기간을 선택할 수 있습니다.");
        setValue(L.HELP_STATISTICS_KEEP_MONTHS_INSTANCE, "오래된 날짜는 하루에 한 번 모든 사용자의 통계에서 영구 삭제됩니다. 0이면 모두 보관합니다. 사용자는 자신에게 더 짧은 기간을 선택할 수 있습니다.");
        setValue(L.HELP_JOBS_ADMIN, "외부 AI와 통신하는 모든 작업(생성, 요약, 오디오북 챕터, 이미지)은 사용자, 시작과 종료, 모델이나 음성 또는 이미지 백엔드에 대한 각 호출과 함께 여기에 기록됩니다. 메타데이터만 보관하며 텍스트는 보관하지 않습니다. 자동으로 삭제되는 것은 없습니다: 필터를 설정하고 일치하는 작업을 삭제하세요.");
        setValue(L.HELP_PLANNER_IMPORT_FROM_BRANCH, "현재 분기 파트의 턴 상세 정보를 장면으로 추가하여 이야기의 재작성을 계획합니다");
        setValue(L.HELP_WORDS_PER_PART, "텍스트는 문단 사이에서 이 단어 수 정도의 파트로 잘립니다. 파트는 두 챕터의 텍스트를 함께 담지 않으며, 챕터 끝에 남는 분량이 이 수의 절반 미만이면 앞 파트에 포함됩니다.");
        setValue(L.HELP_CHAPTER_HEADING_LEVEL, "이 수준과 그 위 수준의 제목이 챕터를 시작하며, 각 챕터는 자신의 제목으로 시작합니다. 더 깊은 제목은 텍스트에 남습니다.");
        setValue(L.HELP_IMPORT_PLACE, "파트는 사용자가 쓴 것으로 추가됩니다. 그 위치 뒤에 오는 내용은 그 뒤로 밀리므로, 그 위치를 다루는 요약은 오래된 것이 됩니다.");
        setValue(L.HELP_CREATE_SUMMARIES, "최신 요약 이후 이야기의 각 블록에 대해 가장 오래된 블록부터 요약을 작성합니다. 이미 있는 요약은 건드리지 않습니다. 블록은 설정이 정한 곳에서 끝나며 모델이 읽을 수 있는 길이보다 길어지지 않습니다.");
        setValue(L.HELP_SUMMARY_CHAPTERS, "챕터는 제목으로 시작하는 파트입니다. 지금까지의 요약이 최소값보다 적은 토큰일 때 시작하는 챕터는 요약을 끝내지 않습니다: 짧은 챕터는 다음 챕터와 함께 요약됩니다.");
        setValue(L.HELP_AFTER_IMPORT, "파트가 책에 들어 있습니다. 긴 이야기를 쓰기 쉽게 해 주는 것은 두 가지입니다: 가져온 내용의 요약과 등장인물과 장소를 담은 로어북. 요약을 먼저 만드세요: 에이전트는 작업하는 동안 책을 잠급니다.");
        setValue(L.HELP_REDRAFT_LENGTH_PROMPT, "재작성을 더 짧게 (더 길게) 요청할 때 지시문에 추가되는 일반 텍스트입니다. 템플릿이 아닙니다. 비워 두면 내장 텍스트입니다.");
        setValue(L.HELP_UPDATE, "서버에 로그인하지 않고 Git 체크아웃에서 Docker 설치를 업데이트합니다: 브랜치의 최신 버전을 가져와 플러그인과 함께 빌드하고 Marginalia를 다시 시작합니다.");
        setValue(L.HELP_AI_CONNECTIONS, "이 모델로 동시에 진행될 수 있는 요청 수: 모든 사용자의 모든 종류의 요청(내 생성, 사이드 쿼리, 에이전트, 플러그인). 나머지는 들어온 순서대로 차례를 기다립니다. 슬롯이 하나인 서버(예: GPU 하나)는 1, 여러 요청에 동시에 응답하는 클라우드 모델은 더 크게 설정할 수 있습니다.");
        setValue(L.HELP_ENTRY_LINKS, "내용에서 다른 항목의 이름이나 키워드를 Ctrl+클릭(Mac에서는 Cmd+클릭)하면 해당 항목이 열리며, Shift를 누르면 새 탭에서 열립니다. 여기에 나열된 항목은 내용에서 이 항목을 언급합니다: 클릭하면 열리고 Shift+클릭하면 새 탭에서 열립니다.");
        setValue(L.HELP_SEND_LORE_IMAGES, "턴이 사용하는 로어북 항목의 내용에 있는 이미지를 로어와 함께 전송합니다. 이미지를 받는 모델에만 해당합니다: 비전이 없는 모델은 요청을 거부합니다.");
        setValue(L.HELP_LORE_IMAGES_IN_SYSTEM, "로어 블록의 이미지를 그 뒤의 별도 메시지가 아니라 시스템 메시지 자체에 넣습니다. 이미지를 거기에 받는 서버와 채팅 템플릿에만 해당하며, 대부분은 그렇지 않습니다.");
        setValue(L.HELP_PROMPT_LANGUAGE, "내장 프롬프트(생성, 요약, 재작성, 주석, 대필, 에이전트)와 플러그인 프롬프트의 언어입니다. 직접 작성한 프롬프트는 그대로 유지되며, 인터페이스 언어는 별도로 설정합니다.");

