        setValue(L.DESC_COMMAND_SEARCH_REPLACE_STORY, "열려 있는 책의 이야기 파트(와 그 요약)를 검색하고, 확인 후 일치 항목을 바꿉니다. 바꿀 내용 뒤의 옵션은 다음 순서입니다: regex (false), 대소문자 구분 (true), 요약에서 검색 (true), 모든 분기에서 검색 (false), 모든 요약 다시 검증 (true).");
        setValue(L.DESC_COMMAND_SEARCH_REPLACE_STORY_LLM, "책의 이야기 텍스트에서 찾기 및 바꾸기: 이야기의 파트와 선택적으로 그 요약을, 활성 분기 또는 모든 분기에서. 책을 변경하며 되돌릴 수 없습니다. 사용자에게는 먼저 일치 항목 수를 확인하도록 묻고, 에이전트는 파괴적 모드의 적용을 받습니다. 먼저 세어 보세요: dryRun이 true이면 아무것도 변경되지 않고 응답이 일치 항목 수를 알려 주며 몇 개를 보여 줍니다. maxHits를 지정하면 그보다 많은 일치 항목이 있는 바꾸기는 거부됩니다. 비동기. 선택 값은 위치 기반이며 순서는 regex, caseSensitive, summaries, allBranches, revalidateSummaries, maxHits, dryRun입니다.");
        setValue(L.DESC_COMMAND_SEARCH_REPLACE_STORY_RETURN, "수행된 작업: 몇 개의 파트에서 몇 개의 일치 항목을 바꿨는지, 또는 아무것도 찾지 못했거나 사용자가 확인하지 않았음");
        setValue(L.DESC_COMMAND_SEARCH_REPLACE_LOREBOOK, "열려 있는 책의 로어북 항목(이름, 텍스트, 메모)을 검색하고, 확인 후 일치 항목을 바꿉니다. 바꿀 내용 뒤의 옵션은 다음 순서입니다: regex (false), 대소문자 구분 (true).");
        setValue(L.DESC_COMMAND_SEARCH_REPLACE_LOREBOOK_LLM, "책의 로어북에서 찾기 및 바꾸기: 루트 로어북 항목의 이름, 텍스트, 메모. 책을 변경하며 되돌릴 수 없습니다. 사용자에게는 먼저 일치 항목 수를 확인하도록 묻고, 에이전트는 파괴적 모드의 적용을 받습니다. 먼저 세어 보세요: dryRun이 true이면 아무것도 변경되지 않고 응답이 일치 항목 수를 알려 주며 몇 개를 보여 줍니다. maxHits를 지정하면 그보다 많은 일치 항목이 있는 바꾸기는 거부됩니다. 비동기. 선택 값은 위치 기반이며 순서는 regex, caseSensitive, maxHits, dryRun입니다.");
