        setValue(L.DESC_COMMAND_LIST_PARTS, "분기의 파트를 위치, 크기, 스와이프, 미리 보기와 함께 나열합니다.");
        setValue(L.DESC_COMMAND_LIST_PARTS_LLM, "이야기의 첫 파트부터 분기의 파트를 나열합니다: 위치, 스와이프(대안) 수, 단어, 토큰, 요약의 상태(없음, 유효, 오래됨), 짧은 미리 보기. 페이지 단위: offset과 limit. 파트는 핸들(목록의 \"handle\"이며 파트가 추가되거나 삭제되어도 바뀌지 않으므로 권장) 또는 분기에서의 위치(이야기의 첫 파트는 1)로 지정하며, 분기는 그 분기의 파트 핸들이나 list-branches의 분기 번호를 주지 않으면 활성 분기입니다. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다. 모든 행에는 \"handle\"도 있으며, 항목이 추가되거나 삭제되어도 바뀌지 않고 책을 변경하는 명령이 이를 받습니다.");
        setValue(L.DESC_COMMAND_LIST_PARTS_RETURN, "페이지의 파트를 담은 JSON: 위치, 스와이프, 단어, 토큰, 요약 상태, 미리 보기");
