        setValue(L.DESC_COMMAND_LIST_SWIPES_RETURN, "스와이프를 담은 JSON: number, shown, words, preview, branch");
        setValue(L.DESC_COMMAND_LIST_BRANCHES, "책의 분기를 번호와 함께 나열합니다.");
        setValue(L.DESC_COMMAND_LIST_BRANCHES_LLM, "이야기의 분기를 나열합니다. 분기는 첫 파트에서 끝 중 하나까지 이어지는 경로입니다. 각 분기에는 번호(다른 명령의 branch로 전달하며, 번호는 끝이 생성된 순서를 따르고 분기가 추가되거나 삭제되면 바뀝니다), 활성 분기 여부, 파트, 단어, 다른 분기와 갈라지는 위치, 끝의 미리 보기가 있습니다. 페이지 단위: offset과 limit. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다. 모든 행에는 \"handle\"도 있으며, 항목이 추가되거나 삭제되어도 바뀌지 않고 책을 변경하는 명령이 이를 받습니다.");
        setValue(L.DESC_COMMAND_LIST_BRANCHES_RETURN, "분기를 담은 JSON: number, active, parts, words, forkPosition, created, endPreview");
        setValue(L.DESC_COMMAND_GET_PART_METRICS, "파트의 토큰, 소요 시간, 모델, 프로토콜을 보여 줍니다.");
        setValue(L.DESC_COMMAND_GET_PART_METRICS_LLM, "생성된 파트의 수치: 토큰과 단어, 프롬프트 및 추론 토큰, 파트를 쓴 모델과 프로토콜, 첫 토큰까지의 시간, 추론 시간. 파트는 핸들(목록의 \"handle\"이며 파트가 추가되거나 삭제되어도 바뀌지 않으므로 권장) 또는 분기에서의 위치(이야기의 첫 파트는 1)로 지정하며, 분기는 그 분기의 파트 핸들이나 list-branches의 분기 번호를 주지 않으면 활성 분기입니다. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다.");
        setValue(L.DESC_COMMAND_GET_PART_METRICS_RETURN, "파트의 지표를 담은 JSON");
        setValue(L.DESC_COMMAND_SHOW_PROMPT, "생성된 파트를 만든 프롬프트를 보여 줍니다.");
        setValue(L.DESC_COMMAND_SHOW_PROMPT_LLM, "파트가 생성될 때 전송되어 파트와 함께 저장된 프롬프트: 텍스트의 조각(offset, length), 토큰 수, 섹션별 토큰 내역, 추가된 배경 로어. 생성되지 않았거나 프롬프트가 저장되기 전에 생성된 파트에는 없습니다. 파트는 핸들(목록의 \"handle\"이며 파트가 추가되거나 삭제되어도 바뀌지 않으므로 권장) 또는 분기에서의 위치(이야기의 첫 파트는 1)로 지정하며, 분기는 그 분기의 파트 핸들이나 list-branches의 분기 번호를 주지 않으면 활성 분기입니다. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다.");
        setValue(L.DESC_COMMAND_SHOW_PROMPT_RETURN, "프롬프트의 조각, 토큰 수, 토큰 내역을 담은 JSON");
        setValue(L.DESC_COMMAND_SEARCH_PARTS, "모든 분기의 파트에서 단어를 검색합니다.");
        setValue(L.DESC_COMMAND_SEARCH_PARTS_LLM, "모든 분기의 파트에 대한 전문 검색: 질의의 모든 단어가 파트에 있어야 합니다 (구문은 큰따옴표, *는 임의의 문자와 일치). 각 결과에는 파트의 위치, 활성 분기가 아닌 경우 분기 번호, 일치 부분 주변의 스니펫이 있습니다. includeVersions를 지정하면 파트의 이전 버전(기록)도 검색합니다: 버전을 통해서만 발견된 파트에는 ID, 시간, 출처가 있는 \"version\"이 있으며 스니펫은 해당 버전의 것입니다. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다. 모든 행에는 \"handle\"도 있으며, 항목이 추가되거나 삭제되어도 바뀌지 않고 책을 변경하는 명령이 이를 받습니다.");
        setValue(L.DESC_COMMAND_SEARCH_PARTS_RETURN, "결과를 담은 JSON: position, branch, snippet");
        setValue(L.DESC_COMMAND_FIND_OCCURRENCES, "이야기에서 이름이나 단어가 나오는 곳을 셉니다.");
        setValue(L.DESC_COMMAND_FIND_OCCURRENCES_LLM, "토큰이 아니라 코드로 수행하는 연속성 검사: 각 용어(이름과 그 변형)에 대해 파트 수와 등장 횟수, 스니펫이 있는 첫 파트들. allBranches가 true가 아니면 활성 분기를 검색하며, summaries가 true이면 요약도 검색합니다. 옵션 순서: regex (false), caseSensitive (false), summaries (false), allBranches (false), limit (용어당 나열할 최대 파트 수, 50). 읽기만 합니다. 모든 행에는 \"handle\"도 있으며, 항목이 추가되거나 삭제되어도 바뀌지 않고 책을 변경하는 명령이 이를 받습니다.");
        setValue(L.DESC_COMMAND_FIND_OCCURRENCES_RETURN, "용어별 JSON: 발견된 파트와 등장 횟수 및 위치");
        setValue(L.DESC_COMMAND_COMPARE_PARTS, "두 파트 사이에서 다른 문장을 보여 줍니다.");
        setValue(L.DESC_COMMAND_COMPARE_PARTS_LLM, "두 파트를 문장 단위로 비교하여 한쪽에만 있는 문장을 최대 200개까지 나열합니다 (-는 첫 번째, +는 두 번째). 두 스와이프를 비교하려면 위치(같음)와 list-swipes의 분기 번호를 지정하세요. 두 번째 위치로 0을 주면 첫 파트를 모델이 처음 생성한 텍스트와 비교하여 작성자가 편집한 내용을 볼 수 있습니다. 위치는 분기(분기 번호를 주지 않으면 활성 분기)에서의 것입니다. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다.");
        setValue(L.DESC_COMMAND_COMPARE_PARTS_RETURN, "개수와 다른 문장을 담은 JSON");
