        setValue(L.DESC_COMMAND_LIST_SUMMARIES_RETURN, "요약을 담은 JSON: position, covers, type, tokens, valid");
        setValue(L.DESC_COMMAND_GET_SUMMARY, "파트의 요약을 읽습니다.");
        setValue(L.DESC_COMMAND_GET_SUMMARY_LLM, "파트에 저장된 요약: 텍스트, 토큰, 유형, 여전히 이야기를 설명하는지 여부. 요약은 그것이 다루는 파트 중 마지막 파트에 저장되므로 대부분의 파트에는 없습니다 (hasSummary false). 파트는 핸들(목록의 \"handle\"이며 파트가 추가되거나 삭제되어도 바뀌지 않으므로 권장) 또는 분기에서의 위치(이야기의 첫 파트는 1)로 지정하며, 분기는 그 분기의 파트 핸들이나 list-branches의 분기 번호를 주지 않으면 활성 분기입니다. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다.");
        setValue(L.DESC_COMMAND_GET_SUMMARY_RETURN, "파트의 요약을 담은 JSON");
