        setValue(L.DESC_COMMAND_CHECK_SUMMARIES_LLM, "분기의 오래된 요약(생성이 제외함)을 찾습니다: 위치와 다루는 파트. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다. 모든 행에는 \"handle\"도 있으며, 항목이 추가되거나 삭제되어도 바뀌지 않고 책을 변경하는 명령이 이를 받습니다.");
        setValue(L.DESC_COMMAND_CHECK_SUMMARIES_RETURN, "요약의 수와 오래된 요약 및 그것이 다루는 파트를 담은 JSON");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES, "책 또는 파트의 템플릿 변수를 보여 줍니다.");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES_LLM, "프롬프트 템플릿이 setvar로 설정한 변수: 책의 전역 변수(scope global), 또는 분기를 따르는 파트의 변수(scope part. 위치를 주지 않으면 분기의 마지막 파트). 파트는 핸들(목록의 \"handle\"이며 파트가 추가되거나 삭제되어도 바뀌지 않으므로 권장) 또는 분기에서의 위치(이야기의 첫 파트는 1)로 지정하며, 분기는 그 분기의 파트 핸들이나 list-branches의 분기 번호를 주지 않으면 활성 분기입니다. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다.");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES_RETURN, "변수와 그 값을 담은 JSON");
