        setValue(L.DESC_COMMAND_LIST_LOREBOOKS, "열려 있는 책의 로어북을 항목 및 하위 책과 함께 나열합니다.");
        setValue(L.DESC_COMMAND_LIST_LOREBOOKS_LLM, "책의 로어북을 나열합니다: 루트 로어북과 그 하위 책의 트리. 각각 번호(루트는 1), 이름, 사용 여부, 항목 수(와 사용 중인 수), 태그, 하위 책의 번호가 있습니다. 사용자의 다른 로어북에는 접근할 수 없습니다. 로어북과 항목은 핸들(권장) 또는 번호로 지정합니다: 로어북은 이 번호로, 항목은 로어북 안의 번호로. 읽기만 합니다. 모든 행에는 \"handle\"도 있으며, 항목이 추가되거나 삭제되어도 바뀌지 않고 책을 변경하는 명령이 이를 받습니다.");
        setValue(L.DESC_COMMAND_LIST_LOREBOOKS_RETURN, "로어북을 담은 JSON: number, name, enabled, entries, enabledEntries, tags, subbooks");
        setValue(L.DESC_COMMAND_LIST_LORE_ENTRIES, "로어북의 항목을 설정 및 미리 보기와 함께 나열합니다.");
        setValue(L.DESC_COMMAND_LIST_LORE_ENTRIES_LLM, "로어북의 항목을 나열합니다 (list-lorebooks의 로어북 번호를 주지 않으면 루트 로어북): 로어북 안의 항목 번호, 이름, 사용 여부, 순서, 삽입 모드, 필터 모드(KEYWORDS_OR / KEYWORDS_AND 키, TEXT 또는 REGEX), 태그, 텍스트 길이, 짧은 미리 보기. 필터는 이름이나 태그에 포함된 항목만 남기며, 번호는 로어북 전체 기준 그대로입니다. 페이지 단위: offset과 limit. 항목은 로어북 안의 번호(첫 항목은 1)로 지정합니다. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다. 모든 행에는 \"handle\"도 있으며, 항목이 추가되거나 삭제되어도 바뀌지 않고 책을 변경하는 명령이 이를 받습니다.");
