        setValue(L.DESC_COMMAND_GET_LORE_ENTRY, "로어북 항목 하나를 설정 및 텍스트와 함께 보여 줍니다.");
        setValue(L.DESC_COMMAND_GET_LORE_ENTRY_LLM, "로어북의 항목 하나를 읽습니다 (list-lorebooks의 로어북 번호를 주지 않으면 루트 로어북): 이름, 사용 여부, 순서, 삽입 모드, 필터 모드와 키(항목을 활성화하는 텍스트나 정규식), 태그와 제외 태그, 메모, offset과 전체 길이가 있는 텍스트 조각 (긴 텍스트는 offset과 length로 넘겨 봄). 항목은 핸들 또는 로어북 안의 번호(첫 항목은 1, list-lore-entries 참조)로 지정합니다. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다. 모든 행에는 \"handle\"도 있으며, 항목이 추가되거나 삭제되어도 바뀌지 않고 책을 변경하는 명령이 이를 받습니다.");
