        setValue(L.DESC_COMMAND_SEARCH_LORE_LLM, "이름, 텍스트, 메모에 질의가 포함된 책의 모든 로어북의 항목을 찾습니다 (대소문자 무시. regex를 사용하면 질의는 정규식). 각 결과에는 로어북 번호, 항목 번호, 이름, 이름/텍스트/메모 중 일치한 곳, 첫 일치 주변의 스니펫이 있습니다. found는 일치하는 항목 수이고 hits는 제한됩니다. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다. 모든 행에는 \"handle\"도 있으며, 항목이 추가되거나 삭제되어도 바뀌지 않고 책을 변경하는 명령이 이를 받습니다.");
        setValue(L.DESC_COMMAND_SEARCH_LORE_RETURN, "found와 결과를 담은 JSON: lorebook, entry, name, matchedIn, snippet");
        setValue(L.DESC_COMMAND_PREVIEW_TEXT_PARAM, "턴의 사용자 프롬프트처럼 항목의 필터를 찾는 대상 텍스트");
        setValue(L.DESC_COMMAND_PREVIEW_LORE_ACTIVATION, "텍스트나 파트에 대해 생성이 어떤 로어북 항목을 사용할지와 그 이유를 보여 줍니다.");
        setValue(L.DESC_COMMAND_PREVIEW_LORE_ACTIVATION_LLM, "텍스트에 대해, 또는 파트를 만든 것과 같은 턴(위치와 선택적으로 분기 번호로 지정)에 대해 생성이 책의 로어북의 어떤 항목을 프롬프트에 넣을지 알려 줍니다: 항목의 필터는 텍스트에서, 파트가 있으면 파트와 함께 저장된 지시문, 장면, 시점, 등장인물로 렌더링한 책의 사용자 프롬프트에서 찾습니다. 사용되는 각 항목에는 로어북 번호, 항목 번호, 이름, 이유(CONSTANT: 필터 없음, FILTER_MATCHED)가 있고, 사용되지 않는 항목에도 이유가 있습니다 (DISABLED, 책의 태그에 대한 NEGATIVE_TAG 또는 MISSING_TAG, FILTER_NOT_MATCHED). 또한 삽입될 로어 텍스트와 그 토큰이 로어 블록과 사용자 프롬프트 앞에 들어가는 로어로 나뉘어 표시됩니다. 여기서 항목의 템플릿은 이야기의 나머지 부분을 사용할 수 없습니다. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다. 모든 행에는 \"handle\"도 있으며, 항목이 추가되거나 삭제되어도 바뀌지 않고 책을 변경하는 명령이 이를 받습니다.");
        setValue(L.DESC_COMMAND_PREVIEW_LORE_ACTIVATION_RETURN, "사용된 항목과 사용되지 않은 항목(이유 포함), 로어 텍스트와 그 토큰을 담은 JSON");
        setValue(L.DESC_AGENT_COMMAND_COMPACT, "지금까지의 모든 것을 요약하고 이전 라운드를 요약으로 대체하여 컨텍스트를 비웁니다. 인수가 있으면 요약이 강조해야 할 내용입니다.");
        setValue(L.DESC_AGENT_COMMAND_CLEAR_WORKSPACE, "에이전트 작업 공간의 모든 파일과 폴더를 삭제합니다. 인수는 유지할 파일, 폴더(안의 내용 포함) 또는 *.md 같은 패턴이며 공백으로 구분합니다 (공백이 있는 경로는 큰따옴표). 유지할 파일 위의 폴더는 남습니다. 유지할 것이 없으면 아무것도 삭제되지 않습니다.");
        setValue(L.DESC_COMMAND_OLD_PARAM, "바꿀 텍스트로, 파트에 있는 그대로여야 하며 정확히 한 번만 발견되어야 합니다");
        setValue(L.DESC_COMMAND_NEW_PARAM, "대신 넣을 텍스트이며, 비워 두면 기존 텍스트를 삭제합니다");
        setValue(L.DESC_COMMAND_WRITE_FIELD_PARAM, "변경할 필드: response (파트의 텍스트, 기본값), instructions, scene, pov 또는 present");
        setValue(L.DESC_COMMAND_NEW_TEXT_PARAM, "텍스트");
