        setValue(L.DESC_COMMAND_TURN_INSTRUCTIONS_PARAM, "파트를 만든 턴의 지시문. 비우면 지우고, 생략하면 그대로 둠");
        setValue(L.DESC_COMMAND_TURN_SCENE_PARAM, "턴의 장면 배경. 비우면 지우고, 생략하면 그대로 둠");
        setValue(L.DESC_COMMAND_TURN_POV_PARAM, "턴의 시점 인물. 비우면 지우고, 생략하면 그대로 둠");
        setValue(L.DESC_COMMAND_TURN_PRESENT_PARAM, "턴의 등장인물. 비우면 지우고, 생략하면 그대로 둠");
        setValue(L.DESC_COMMAND_EDIT_PART, "파트 텍스트의 일부를 다른 텍스트로 바꿉니다. 매개변수: part (핸들), old, new, field.");
        setValue(L.DESC_COMMAND_EDIT_PART_LLM, "이야기의 파트를 변경합니다: 텍스트 조각 `old`가 `new`로 바뀝니다. `old`는 파트에서 정확히 한 번 일치해야 하며 (공백과 줄 바꿈까지 동일), 그렇지 않으면 아무것도 변경되지 않고 오류가 몇 번 발견되었는지 알려 줍니다: 주변 텍스트를 더 포함하세요. 파트는 핸들로 지정합니다. 단어와 토큰을 다시 세고 어떤 요약이 오래된 것이 되었는지 알려 줍니다 (내용이 여전히 맞다면 revalidate-summaries를 실행하고, 그렇지 않으면 다시 생성하세요). `field`를 지정하면 텍스트 대신 턴의 지시문, 장면, 시점, 등장인물을 편집합니다. 책을 변경합니다.");
        setValue(L.DESC_COMMAND_EDIT_PART_RETURN, "파트(handle, position, words, tokens)와 오래된 것이 된 요약을 담은 JSON");
        setValue(L.DESC_COMMAND_REPLACE_PART_TEXT, "파트의 전체 텍스트를 바꿉니다. 매개변수: part (핸들), text, field.");
        setValue(L.DESC_COMMAND_REPLACE_PART_TEXT_LLM, "이야기의 파트의 전체 텍스트를 `text`로 바꿉니다 (`field`를 지정하면 턴의 지시문, 장면, 시점, 등장인물 전체). 기존 텍스트는 사라지므로 작은 변경에는 edit-part를, 끝에 추가하려면 append-to-part를 사용하세요. 파트는 핸들로 지정합니다. 단어와 토큰을 다시 세고 어떤 요약이 오래된 것이 되었는지 알려 줍니다. 책을 변경합니다. 사용자에게는 확인을 묻고, 에이전트는 파괴적 모드의 적용을 받습니다.");
        setValue(L.DESC_COMMAND_REPLACE_PART_TEXT_RETURN, "파트(handle, position, words, tokens)와 오래된 것이 된 요약을 담은 JSON");
        setValue(L.DESC_COMMAND_APPEND_TO_PART, "파트의 끝에 텍스트를 추가합니다. 매개변수: part (핸들), text, separator.");
        setValue(L.DESC_COMMAND_APPEND_TO_PART_LLM, "이야기의 파트 텍스트 끝에 `separator` 뒤로 `text`를 추가합니다 (생략하면 빈 줄, 파트가 비어 있으면 없음). 파트를 이어 쓸 때 사용하세요. 새 파트를 쓰려면 create-part를 사용하세요. 파트는 핸들로 지정합니다. 단어와 토큰을 다시 세고 어떤 요약이 오래된 것이 되었는지 알려 줍니다. 책을 변경합니다.");
        setValue(L.DESC_COMMAND_APPEND_TO_PART_RETURN, "파트(handle, position, words, tokens)와 오래된 것이 된 요약을 담은 JSON");
