        setValue(L.DESC_COMMAND_SET_PART_FIELDS_LLM, "이야기의 파트와 함께 저장된 턴 입력을 변경합니다: 지시문, 장면 배경, 시점 인물, 등장인물이며, 파트의 새 생성(스와이프, 재생성)은 이것으로 다시 만들어집니다. 지정한 필드만 변경되며, 빈 텍스트는 필드를 지웁니다. 파트의 텍스트는 변경하지 않습니다. 파트는 핸들로 지정합니다. 책을 변경합니다.");
