        setValue(L.DESC_COMMAND_CREATE_PART_LLM, "주어진 텍스트로 이야기에 새 파트를 추가합니다: 파트 `parent`(핸들) 뒤에, 또는 `parent`를 생략하면 활성 분기의 마지막 파트 뒤에 (빈 책에서는 첫 파트). 이미 이어지는 파트가 있는 파트를 이어가는 파트는 새 분기를 시작합니다. 새 파트는 활성 분기의 끝이 됩니다. 선택적으로 해당 파트가 대표하는 턴 입력(instructions, scene, pov, present)을 저장합니다. 직접 텍스트를 쓸 때 사용하고, 모델이 쓰게 하려면 next를 사용하세요. 책을 변경합니다. 새 파트의 핸들을 반환합니다.");
