        setValue(L.DESC_COMMAND_BRANCH_PART_LLM, "파트(와 그 요약)를 형제로 복사합니다. 새 분기를 시작하는 새 스와이프이며, 사본이 활성 분기의 끝이 됩니다. 원본을 뒤따르던 파트는 원본에 남습니다. 첫 버전을 잃지 않고 파트의 다른 버전을 시도할 때 사용하세요. 파트는 핸들로 지정합니다. 책을 변경합니다. 사본의 핸들을 반환합니다.");
