        setValue(L.DESC_COMMAND_SWITCH_BRANCH_LLM, "파트를 지나는 분기를 책의 활성 분기로 만듭니다: 그 끝은 파트 아래에서 가장 새로운 이어쓰기입니다. 다른 스와이프를 선택하는 것과 같습니다. 파트는 핸들로 지정합니다 (list-swipes와 list-branches 참조). 분기를 지정하지 않는 명령이 작업하는 파트와 다음 생성이 이어가는 곳이 바뀝니다. 책을 변경합니다.");
        setValue(L.DESC_COMMAND_SWITCH_BRANCH_RETURN, "파트, 분기 끝의 핸들, 그 길이를 담은 JSON");
