        setValue(L.DESC_COMMAND_SET_SUMMARY_LLM, "이야기의 파트에 붙어 있는 요약의 텍스트를 바꿉니다 (파트에 요약이 있어야 함). 요약은 그 파트까지의 파트를 대표하며 토큰이 다시 계산됩니다. 이를 포함하는 위의 메타 요약이 오래된 것이 될 수 있습니다 (응답에 나열됨). 파트는 핸들로 지정합니다. 책을 변경합니다.");
        setValue(L.DESC_COMMAND_SET_SUMMARY_RETURN, "파트, 요약의 토큰, 오래된 것이 된 요약을 담은 JSON");
