        setValue(L.DESC_COMMAND_REMOVE_SUMMARY_LLM, "이야기의 파트에 붙어 있는 요약을 제거하여 생성이 그 대신 파트 자체를 다시 사용하게 합니다. `unwind`를 지정하면 메타 요약은 대신 자신이 대체했던 요약으로 교체됩니다. 파트는 핸들로 지정합니다. 책을 변경합니다. 사용자에게는 확인을 묻고, 에이전트는 파괴적 모드의 적용을 받습니다.");
