        setValue(L.DESC_COMMAND_REVALIDATE_SUMMARIES_LLM, "편집으로 오래된 것이 된 요약을 다시 유효한 것으로 표시합니다: 요약이 설명하는 이야기의 해시를 새로 계산합니다. 편집 후에도 요약의 내용이 여전히 맞다고 확인한 경우에만 사용하세요 (오타 수정, 이름 변경). 바뀐 사건을 설명하는 요약은 regenerate-summary로 다시 만들어야 합니다. `part`가 없으면 활성 분기의 모든 요약, `part`가 있으면 해당 파트(핸들)의 요약만 대상입니다. 책을 변경합니다.");
