        setValue(L.DESC_COMMAND_SET_BOOK_INFO, "책의 이름, 설명, 시점, 시제, 문체, 언어를 변경합니다. 매개변수: name, description, pov, tense, style, language.");
        setValue(L.DESC_COMMAND_SET_BOOK_INFO_LLM, "책의 설명적 설정을 변경합니다: 이름, 설명, 서술 시점, 시제, 문체, 언어. 지정한 값만 변경되고 나머지는 유지됩니다 (빈 텍스트는 필드를 지우며 이름은 비울 수 없음). 언어, 시점, 시제, 문체는 생성 프롬프트에 사용됩니다. 모델, 로어북, 프롬프트 템플릿은 여기서 변경되지 않습니다. 책을 변경합니다.");
