        setValue(L.DESC_COMMAND_SET_BOOK_PROMPTS_LLM, "책의 생성에 사용되는 프롬프트 템플릿을 바꿉니다: 마스터 템플릿(시스템 프롬프트), 턴의 사용자 프롬프트, 요약 및 메타 요약의 프롬프트. 지정한 템플릿만 변경됩니다. 각각 먼저 검사합니다: 올바르지 않은 템플릿은 거부되고 아무것도 변경되지 않으며, 존재하지 않는 이름을 사용하는 템플릿은 저장되고 응답이 어떤 것인지 알려 줍니다. 이후 책의 모든 생성이 이 템플릿을 사용하므로 잘못된 템플릿은 이야기를 망칩니다: 요청받았을 때만 변경하세요. 책을 변경합니다. 사용자에게는 확인을 묻고, 에이전트는 파괴적 모드의 적용을 받습니다.");
