        setValue(L.DESC_COMMAND_SET_BOOK_TAGS, "책에 태그를 추가하거나 제거합니다. 매개변수: add, remove (쉼표로 구분).");
        setValue(L.DESC_COMMAND_SET_BOOK_TAGS_LLM, "책에 태그를 추가하고 책에서 태그를 제거합니다. 둘 다 쉼표로 구분한 목록이며 둘 중 하나는 생략할 수 있습니다. 책의 태그는 태그로 제한된 로어북 항목 중 어느 것이 사용되는지를 결정합니다. 존재하지 않는 태그는 만들어집니다. 책을 변경합니다.");
