        setValue(L.DESC_COMMAND_CREATE_LORE_ENTRY_LLM, "책의 로어북에 새 항목을 추가합니다 (`lorebook`을 생략하면 루트 로어북). `payload`는 프롬프트에 들어가는 텍스트이며 Handlebars 템플릿입니다. `keys`가 없는 항목은 항상 사용되고, 그렇지 않으면 키가 턴의 텍스트에 있을 때 사용됩니다: `keys`는 쉼표로 구분한 단어 목록 (예: \"Anna, Novak\")이며, 그중 하나라도 있으면 (filteringMode KEYWORDS_OR, 기본값) 또는 모두 있으면 (KEYWORDS_AND) 항목이 사용됩니다. filteringMode TEXT는 `keys` 전체를 하나의 텍스트로, REGEX는 정규식으로 취급합니다. 템플릿이나 정규식의 문제는 저장을 막지 않으며 응답에 보고됩니다: update-lore-entry로 수정하세요. `order`(낮을수록 먼저, 생략하면 100)는 사용된 항목 중에서 항목을 앞이나 뒤에 놓습니다: list-lore-entries로 다른 항목의 `order`를 읽어 그 사이에 배치하세요. `insertionMode` BEFORE_USER_PROMPT는 텍스트를 로어 블록에서 요청 바로 앞으로 옮깁니다. 책을 변경합니다. 항목의 핸들을 반환합니다.");
        setValue(L.DESC_COMMAND_CREATE_LORE_ENTRY_RETURN, "항목(handle, name)과 텍스트나 필터의 문제(있는 경우)를 담은 JSON");
        setValue(L.DESC_COMMAND_UPDATE_LORE_ENTRY, "로어북 항목의 필드를 변경합니다. 매개변수: entry (핸들), name, payload, comment, enabled, order, keys, filteringMode, insertionMode.");
        setValue(L.DESC_COMMAND_UPDATE_LORE_ENTRY_LLM, "주어진 핸들의 항목을 변경합니다: 지정한 필드만 변경됩니다. 긴 텍스트의 일부를 바꾸려면 get-lore-entry로 읽고 전체 새 `payload`를 지정하세요. 템플릿이나 정규식의 문제는 저장을 막지 않으며 응답에 보고됩니다. `order`와 `insertionMode`는 프롬프트에서 항목의 위치를 옮깁니다 (create-lore-entry 참조). 태그를 바꾸려면 set-lore-entry-tags를, 이동하려면 move-lore-entry를 사용하세요. 책을 변경합니다.");
        setValue(L.DESC_COMMAND_UPDATE_LORE_ENTRY_RETURN, "항목(handle, name)과 텍스트나 필터의 문제(있는 경우)를 담은 JSON");
        setValue(L.DESC_COMMAND_DELETE_LORE_ENTRY, "로어북의 항목을 삭제합니다. 매개변수: entry (핸들).");
        setValue(L.DESC_COMMAND_DELETE_LORE_ENTRY_LLM, "주어진 핸들의 항목을 로어북에서 삭제합니다. 로어북에서 그 뒤에 오는 항목의 번호는 바뀌지만 핸들은 바뀌지 않습니다. 책을 변경합니다. 사용자에게는 확인을 묻고, 에이전트는 파괴적 모드의 적용을 받습니다.");
        setValue(L.DESC_COMMAND_DELETE_LORE_ENTRY_RETURN, "삭제된 항목의 핸들과 이름을 담은 JSON");
        setValue(L.DESC_COMMAND_MOVE_LORE_ENTRY, "항목을 책의 다른 로어북으로 이동합니다. 매개변수: entry (핸들), lorebook (핸들).");
        setValue(L.DESC_COMMAND_MOVE_LORE_ENTRY_LLM, "항목을 책의 다른 로어북(루트 로어북 또는 하위 책)으로 이동합니다. 필드와 태그는 유지됩니다. 책을 변경합니다.");
        setValue(L.DESC_COMMAND_MOVE_LORE_ENTRY_RETURN, "항목(handle, name)과 텍스트나 필터의 문제(있는 경우)를 담은 JSON");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_TAGS, "항목의 태그와 제외 태그를 추가하거나 제거합니다. 매개변수: entry (핸들), add, remove, addNegative, removeNegative (쉼표로 구분).");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_TAGS_LLM, "주어진 핸들의 항목의 태그를 변경합니다. 각 목록은 쉼표로 구분하며 생략할 수 있습니다. 태그가 있는 항목은 그중 하나가 있는 책에서만 사용되고, 제외 태그가 있는 항목은 그중 하나가 있는 책에서 사용되지 않습니다 (책의 태그, set-book-tags 참조). 존재하지 않는 태그는 만들어집니다. 책을 변경합니다.");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_TAGS_RETURN, "변경 후 항목의 태그와 제외 태그를 담은 JSON");
        setValue(L.DESC_COMMAND_CREATE_LOREBOOK, "다른 로어북의 하위 책인 새 로어북을 만듭니다. 매개변수: name, parent (핸들).");
        setValue(L.DESC_COMMAND_CREATE_LOREBOOK_LLM, "새로운 빈 로어북을 만들어 로어북 `parent`(생략하면 루트 로어북)의 하위 책으로 추가하므로, 그 항목이 책에서 사용됩니다. 책을 변경합니다. 새 로어북의 핸들을 반환합니다.");
        setValue(L.DESC_COMMAND_CREATE_LOREBOOK_RETURN, "새 로어북(handle, number, name)을 담은 JSON");
        setValue(L.DESC_COMMAND_SET_LOREBOOK, "로어북의 이름을 바꾸거나 켜고 끕니다. 매개변수: lorebook (핸들), name, enabled.");
        setValue(L.DESC_COMMAND_SET_LOREBOOK_LLM, "책의 로어북의 이름이나 사용 여부를 변경합니다: 비활성화된 로어북의 항목은 사용되지 않습니다. 지정한 값만 변경됩니다. 책을 변경합니다.");
        setValue(L.DESC_COMMAND_SET_LOREBOOK_RETURN, "로어북(handle, number, name, enabled)을 담은 JSON");
        setValue(L.DESC_COMMAND_ADD_SUBBOOK, "책의 로어북을 다른 로어북의 하위 책으로 만듭니다. 매개변수: lorebook (핸들), subbook (핸들).");
        setValue(L.DESC_COMMAND_ADD_SUBBOOK_LLM, "로어북 `subbook`을 로어북 `lorebook`의 하위 책으로 만들어, 그 항목이 `lorebook`이 사용되는 곳 어디서나 사용되게 합니다. 둘 다 이 책의 로어북이어야 하며, 로어북은 직접적으로나 하위 책을 통해서나 자기 자신을 포함할 수 없습니다 (거부됨). 이번 실행에서 앞서 삭제되었거나 부모에서 빼낸 로어북은 핸들로 `subbook`에 지정할 수 있으며, 추가하면 항목과 함께 되살아납니다. 책을 변경합니다.");
        setValue(L.DESC_COMMAND_ADD_SUBBOOK_RETURN, "로어북과 그 하위 책을 담은 JSON");
        setValue(L.DESC_COMMAND_REMOVE_SUBBOOK, "로어북이 다른 로어북의 하위 책이 아니게 합니다. 매개변수: lorebook (핸들), subbook (핸들).");
        setValue(L.DESC_COMMAND_REMOVE_SUBBOOK_LLM, "로어북 `subbook`을 로어북 `lorebook`의 하위 책에서 뺍니다. 하위 책이 아니면 아무 일도 일어나지 않습니다. 로어북은 삭제되지 않지만, 다른 로어북이 이를 하위 책으로 갖고 있지 않으면 그 항목은 더 이상 책에서 사용되지 않으며, 핸들로 지정하여 add-subbook으로 다시 추가할 수 있습니다. 책을 변경합니다.");
        setValue(L.DESC_COMMAND_REMOVE_SUBBOOK_RETURN, "로어북과 그 하위 책을 담은 JSON");
        setValue(L.DESC_COMMAND_DELETE_LOREBOOK, "로어북을 항목과 함께 삭제합니다. 매개변수: lorebook (핸들).");
        setValue(L.DESC_COMMAND_DELETE_LOREBOOK_LLM, "책의 로어북을 모든 항목과 함께 삭제하고, 이를 가지고 있던 로어북의 하위 책에서 뺍니다. 삭제된 것으로 표시만 됩니다: 핸들로 add-subbook을 하면 항목과 함께 되살아납니다. 책의 루트 로어북은 삭제할 수 없습니다. 책을 변경합니다. 사용자에게는 확인을 묻고, 에이전트는 파괴적 모드의 적용을 받습니다.");
        setValue(L.DESC_COMMAND_DELETE_LOREBOOK_RETURN, "삭제된 로어북의 핸들과 이름, 항목 수를 담은 JSON");
        setValue(L.DESC_COMMAND_MAX_HITS_PARAM, "일치 항목이 이보다 많으면 바꾸기를 거부합니다. 생략하면 제한 없음");
        setValue(L.DESC_COMMAND_DRY_RUN_PARAM, "일치 항목을 세고 몇 개만 보여 줄 뿐 아무것도 변경하지 않습니다. 생략하면 false");
        setValue(L.DESC_COMMAND_GEN_INSTRUCTIONS_PARAM, "새 파트가 해야 할 일이나 담아야 할 내용. 스와이프와 재생성에서는 생략하면 파트를 만든 지시문");
