        setValue(L.DESC_COMMAND_GEN_PRESENT_PARAM, "턴의 등장인물. 스와이프와 재생성에서는 생략하면 파트를 만든 것");
        setValue(L.DESC_COMMAND_AFTER_PART_PARAM, "이어 쓸 파트 (핸들)로, 먼저 활성 분기의 끝이 됩니다. 생략하면 활성 분기의 끝");
        setValue(L.DESC_COMMAND_GEN_PROFILE_PARAM, "쓰는 데 사용할 에이전트의 모델 프로필 중 하나의 역할. 생략하면 주 프로필");
        setValue(L.DESC_COMMAND_GEN_PART_PARAM, "다시 쓸 파트 (핸들). 분기의 마지막 파트여야 합니다. 생략하면 활성 분기의 끝");
        setValue(L.DESC_COMMAND_META_FROM_PARAM, "병합할 범위에서 가장 새로운 파트 (핸들). 메타 요약이 여기에 붙습니다");
        setValue(L.DESC_COMMAND_META_TO_PARAM, "병합할 범위에서 가장 오래된 파트 (핸들)");
        setValue(L.DESC_COMMAND_NEXT, "모델이 이야기의 다음 파트를 쓰게 합니다. 매개변수: scene, pov, present, instructions, after (핸들), profile.");
        setValue(L.DESC_COMMAND_NEXT_LLM, "새 턴 버튼처럼 활성 분기의 끝(또는 파트 `after`)에 이어서 모델이 이야기의 다음 파트를 쓰게 합니다: 프롬프트는 책(템플릿, 로어, 요약, 지금까지의 이야기)과 여기서 지정한 턴 입력으로 구성됩니다. 느리며 책의 모델(또는 에이전트의 `profile`)의 토큰이 듭니다. 책에서는 한 번에 하나의 생성만 실행되고 나머지는 대기합니다. 새 파트는 활성 분기의 끝이 됩니다. 새 파트의 핸들을 반환하며 get-part로 읽을 수 있습니다. 책을 변경합니다. 비동기.");
        setValue(L.DESC_COMMAND_NEXT_RETURN, "새 파트(handle, position, words, tokens, model)와 생성의 경고를 담은 JSON");
        setValue(L.DESC_COMMAND_SWIPE, "모델이 마지막 파트의 다른 버전을 첫 번째 옆에 쓰게 합니다. 매개변수: part (핸들), scene, pov, present, instructions, profile.");
        setValue(L.DESC_COMMAND_SWIPE_LLM, "모델이 파트의 다른 버전(스와이프)을 쓰게 합니다: 같은 턴(또는 여기서 지정한 변경된 턴 입력)으로 만든 파트의 새 형제이며 활성 분기의 끝이 됩니다. 첫 버전은 다른 분기로 남습니다 (list-swipes, switch-branch 참조). 파트는 분기의 마지막 파트여야 합니다. 느리며 토큰이 듭니다. 책에서는 한 번에 하나의 생성만 실행됩니다. 새 파트의 핸들을 반환합니다. 책을 변경합니다. 비동기.");
        setValue(L.DESC_COMMAND_SWIPE_RETURN, "새 파트(handle, position, words, tokens, model)와 생성의 경고를 담은 JSON");
        setValue(L.DESC_COMMAND_REGENERATE, "모델이 마지막 파트를 다시 쓰게 하여 텍스트를 교체합니다. 매개변수: part (핸들), scene, pov, present, instructions, profile.");
        setValue(L.DESC_COMMAND_REGENERATE_LLM, "모델이 분기의 마지막 파트를 다시 쓰게 하고 파트의 텍스트를 그 자리에서 교체합니다 (이전 것을 유지하려면 swipe 사용). 파트는 분기의 마지막 파트여야 합니다. 생성이 실패하지 않는 한 이전 텍스트는 사라지며, 실패하면 그대로 남습니다. 느리며 토큰이 듭니다. 책에서는 한 번에 하나의 생성만 실행됩니다. 파트의 핸들을 반환합니다. 책을 변경합니다. 사용자에게는 확인을 묻고, 에이전트는 파괴적 모드의 적용을 받습니다. 비동기.");
        setValue(L.DESC_COMMAND_REGENERATE_RETURN, "새 파트(handle, position, words, tokens, model)와 생성의 경고를 담은 JSON");
        setValue(L.DESC_COMMAND_REGENERATE_SUMMARY, "모델이 파트에서 끝나는 요약을 다시 만들게 합니다. 매개변수: part (핸들).");
        setValue(L.DESC_COMMAND_REGENERATE_SUMMARY_LLM, "모델이 파트에 붙은 요약(요약 블록의 머리)을 그것이 대표하는 파트들로부터 다시 쓰게 하고, 이전 요약 대신 파트에 붙여서 오래된 요약이 유효해지게 합니다. 느리며 책의 모델의 토큰이 듭니다. 파트는 핸들로 지정합니다. 책을 변경합니다. 비동기.");
        setValue(L.DESC_COMMAND_REGENERATE_SUMMARY_RETURN, "파트, 새 요약의 토큰, 텍스트의 시작 부분을 담은 JSON");
        setValue(L.DESC_COMMAND_CREATE_META_SUMMARY, "모델이 범위의 요약을 하나로 병합하게 합니다. 매개변수: from (핸들), to (핸들).");
        setValue(L.DESC_COMMAND_CREATE_META_SUMMARY_LLM, "모델이 파트 `from`(가장 새로운 것)에서 파트 `to`(가장 오래된 것이며 요약 블록의 끝까지 올림)까지의 요약을 `from`에 붙어서 거기 있던 요약을 대체하는 하나의 메타 요약으로 병합하게 합니다. 긴 이야기를 컨텍스트에 맞출 때 사용하세요. 두 파트는 같은 분기에 있고 요약이 있어야 합니다. 느리며 책의 모델의 토큰이 듭니다. 책을 변경합니다. 비동기.");
        setValue(L.DESC_COMMAND_CREATE_META_SUMMARY_RETURN, "파트, 메타 요약의 토큰, 텍스트의 시작 부분을 담은 JSON");
        setValue(L.DESC_COMMAND_INSERT_PART, "이야기의 두 파트 사이에 새 파트를 삽입합니다. 뒤따르는 파트는 그대로 남습니다. 매개변수: text, part (핸들), before (true 또는 false).");
        setValue(L.DESC_COMMAND_INSERT_PART_LLM, "주어진 텍스트로 이야기의 중간에 새 파트를 삽입합니다: 파트 `part`(핸들) 바로 뒤에, 또는 `before`가 true이면 바로 앞에. 그 위치 뒤에 오던 모든 것(모든 분기)이 이제 새 파트를 뒤따르며, 삭제되거나 다시 쓰이는 파트는 없으므로 다른 파트의 핸들, 요약, 데이터는 그대로 유지됩니다. 새 파트 아래의 모든 파트는 한 위치씩 아래로 이동합니다. 아래의 파트를 삭제하고 다시 만드는 대신 사용하세요. 그 위치를 다루는 요약은 오래된 것이 됩니다 (보고됨. revalidate-summaries나 regenerate-summary로 해결). 분기의 끝에서는 create-part와 같습니다. 책을 변경합니다. 새 파트의 핸들을 반환합니다.");
        setValue(L.DESC_COMMAND_INSERT_PART_RETURN, "새 파트(handle, position, words, tokens), 이를 이어가는 분기의 수, 해당 분기의 길이, 오래된 것이 된 요약을 담은 JSON");
        setValue(L.DESC_COMMAND_INSERT_ANCHOR_PARAM, "새 파트를 삽입할 기준 파트 (핸들): 그 뒤에, 또는 before가 true이면 그 앞에");
        setValue(L.DESC_COMMAND_INSERT_BEFORE_PARAM, "true이면 파트 뒤가 아니라 앞에 삽입합니다. 생략하면 false");
        setValue(L.DESC_TEMPLATE_PREVIOUS_STORY, "파트 앞의 이야기로, 끝부분을 들어가는 만큼 (더 오래된 이야기는 요약에 있음).");
        setValue(L.DESC_TEMPLATE_PART_TEXT, "재작성 중인 파트의 텍스트.");
