        setValue(L.DESC_COMMAND_REDRAFT_PART, "모델이 지시문에 따라 이야기의 파트(마지막 파트뿐 아니라 어느 파트든)를 다시 쓰게 하여 텍스트를 교체합니다. 토큰이 듭니다.");
        setValue(L.DESC_COMMAND_REDRAFT_PART_LLM, "모델이 파트 `part`(핸들)를 다시 쓰게 하고 텍스트를 결과로 교체합니다. 파트는 이야기의 어디에 있어도 됩니다. `instructions`는 바뀌어야 할 내용입니다 (\"대화를 더 넣기\", \"전투를 더 길게\", \"결말은 유지\"). 없으면 같은 사건으로 파트를 다시 씁니다. 모델은 파트, 그 앞의 이야기(오래된 이야기는 요약), 그 뒤의 이야기, 파트를 쓸 때 사용한 로어, 턴의 데이터를 봅니다. `prompt`는 책의 것 대신 사용할 재작성 프롬프트 (변수 text, redraftInstructions, previousStory, summaries, followingStory, backgroundLore, narrativePov, narrativeTense, style, povCharacter, sceneSetting, presentCharacters, instructions가 있는 템플릿), `profile`은 실행의 모델 대신 쓸 에이전트의 모델 프로필, `apply`가 false이면 재작성한 텍스트만 반환하고 파트는 그대로 둡니다 (먼저 보고 나서 replace-part-text). 텍스트를 교체하므로 파트를 다루는 요약은 오래된 것이 됩니다 (보고됨). 느리며 토큰이 듭니다. 파트를 반환하며, apply가 false이면 텍스트도 반환합니다.");
        setValue(L.DESC_COMMAND_REDRAFT_PART_RETURN, "JSON 객체: 파트의 handle, position, words, tokens, applied, 텍스트(apply가 false이면 전체 텍스트), 오래된 요약");
        setValue(L.DESC_COMMAND_REDRAFT_INSTRUCTIONS_PARAM, "파트에서 바뀌어야 할 내용. 비워 두면 같은 사건으로 파트를 다시 씁니다");
        setValue(L.DESC_COMMAND_REDRAFT_PROMPT_PARAM, "책의 것 대신 사용할 재작성 프롬프트 (템플릿). 비워 두면 책의 것");
