        setValue(L.DESC_COMMAND_ANNOTATION_TYPE_PARAM, "메모의 종류를 나타내는 자유 단어 (continuity, style...). 없으면 비워 둠");
        setValue(L.DESC_COMMAND_ANNOTATION_SEND_PARAM, "true이면 파트와 함께 메모를 모델에 전달하고, false이면 전달하지 않음");
        setValue(L.DESC_COMMAND_LIST_ANNOTATIONS, "책 또는 파트의 주석(구절에 대한 메모)을 나열합니다. 매개변수: status, part, offset, limit.");
        setValue(L.DESC_COMMAND_LIST_ANNOTATIONS_LLM, "책의 주석, 즉 파트의 구절(또는 파트 전체)에 붙어 있는 작성자용 메모를 나열합니다. 모든 행에는 \"handle\", 파트의 핸들과 파트가 활성 분기에 있으면 파트의 위치, 상태(open, resolved, dismissed, orphaned: 구절이 사라짐), 출처(author, ai, agent, plugin), 유형, 구절이 있으면 구절(파트 텍스트의 시작 및 끝 offset과 인용한 단어), 메모가 있습니다. 상태를 생략하면 open이며, \"all\"은 모두 나열합니다. 파트(핸들 또는 활성 분기에서의 위치)를 지정하면 목록이 그 파트로 제한됩니다. 읽기만 합니다. 옵션은 위치 기반이고 선택 사항이며 나열된 순서입니다.");
        setValue(L.DESC_COMMAND_LIST_ANNOTATIONS_RETURN, "주석과 페이지 정보를 담은 JSON");
        setValue(L.DESC_COMMAND_GET_ANNOTATION, "주석을 메모와 그것이 가리키는 구절과 함께 보여 줍니다. 매개변수: annotation (핸들).");
        setValue(L.DESC_COMMAND_GET_ANNOTATION_LLM, "주석 하나를 전체로: 메모, 상태, 출처, 유형, 앞뒤 텍스트와 함께 인용한 구절, 파트 안의 위치. 주석은 핸들(list-annotations에서)로 지정합니다. 읽기만 합니다.");
        setValue(L.DESC_COMMAND_GET_ANNOTATION_RETURN, "주석을 담은 JSON");
        setValue(L.DESC_COMMAND_CREATE_ANNOTATION, "파트의 구절에 메모를 추가합니다. 매개변수: part (핸들), text, quote, type.");
        setValue(L.DESC_COMMAND_CREATE_ANNOTATION_LLM, "이야기의 파트의 구절에 작성자용 메모로 주석을 답니다. 이야기의 텍스트는 변경되지 않으며 메모는 모델에 전송되지 않습니다. 구절의 단어를 quote로 한 글자도 틀리지 않게 복사하여 지정하세요 (파트에 한 번만 있다면 몇 단어로 충분합니다): 그러면 메모가 그 구절에 붙고 텍스트가 편집되어도 따라갑니다. quote가 없으면 메모는 파트 전체에 대한 것이며, 텍스트에 없는 quote도 파트 전체에 대한 메모가 되고 응답이 이를 알려 줍니다. type은 자유 단어입니다 (continuity, style...). 파트는 핸들로 지정합니다. 책의 주석에 추가됩니다.");
        setValue(L.DESC_COMMAND_CREATE_ANNOTATION_RETURN, "새 주석을 담은 JSON");
        setValue(L.DESC_COMMAND_UPDATE_ANNOTATION, "주석의 메모, 유형, 프롬프트 전송 플래그를 변경합니다. 매개변수: annotation (핸들), text, type, sendToPrompt.");
        setValue(L.DESC_COMMAND_UPDATE_ANNOTATION_LLM, "주석을 변경합니다: 메모의 텍스트, 유형, 파트와 함께 모델에 전달할지 여부(sendToPrompt). 비어 있는 text나 type은 현재 값을 유지하며, sendToPrompt를 생략하면 플래그가 유지됩니다. 주석은 핸들(list-annotations에서)로 지정합니다. 구절과 상태는 여기서 변경되지 않습니다 (reattach-annotation과 resolve-annotation 참조).");
