        setValue(L.DESC_COMMAND_RESOLVE_ANNOTATION_LLM, "주석을 해결됨(문제를 처리함) 또는 무시됨(처리할 가치가 없음)으로 닫거나 다시 엽니다 (open). 닫힌 주석은 텍스트에서 사라지고 목록에 남습니다. status를 생략하면 resolved입니다. 주석은 핸들(list-annotations에서)로 지정합니다.");
        setValue(L.DESC_COMMAND_RESOLVE_ANNOTATION_RETURN, "주석을 담은 JSON");
        setValue(L.DESC_COMMAND_REATTACH_ANNOTATION, "인용문이 파트에서 찾는 구절에 주석을 연결합니다. 매개변수: annotation (핸들), quote.");
        setValue(L.DESC_COMMAND_REATTACH_ANNOTATION_LLM, "주석을 파트의 다른 구절로 옮깁니다: 구절은 quote로 찾으며, quote는 파트의 텍스트에서 복사해야 합니다. 고아 상태인 주석(구절이 삭제됨)은 다시 열림 상태가 됩니다. 주석은 핸들(list-annotations에서)로 지정합니다. quote가 없으면 주석은 파트 전체에 대한 것이 됩니다.");
        setValue(L.DESC_COMMAND_REATTACH_ANNOTATION_RETURN, "주석을 담은 JSON");
