        setValue(L.DESC_COMMAND_DELETE_ANNOTATION_LLM, "주석을 삭제합니다 (사용자는 휴지통에서 되살릴 수 있음). 주석을 닫되 목록에 남기려면 resolve-annotation을 사용하세요. 주석은 핸들(list-annotations에서)로 지정합니다.");
