        setValue(L.DESC_TEMPLATE_ANNOTATE_INSTRUCTIONS, "작성자가 파트에서 살펴보기를 원하는 것 (지시문이 없으면 비어 있음).");
        setValue(L.DESC_TEMPLATE_OUTPUT_FORMAT, "모델에게 응답을 작성하는 방법을 알려 주는 내용으로, 메모를 요청하는 방식에 따라 달라집니다.");
        setValue(L.DESC_TEMPLATE_STORY_ANNOTATIONS, "프롬프트에서 모델에 전달하도록 표시된, 이야기의 구절에 대한 작성자의 메모. 한 줄에 하나씩 (없으면 비어 있음).");
        setValue(L.DESC_TEMPLATE_SELECTION, "작성자가 다시 쓰도록 선택한 파트의 텍스트 (파트 전체를 재작성하면 비어 있음). 구절의 재작성과 파트 전체의 재작성을 구별합니다.");
        setValue(L.DESC_TEMPLATE_SELECTION_BEFORE, "선택한 구절 앞의 파트 텍스트 (구절을 재작성할 때만).");
