        setValue(L.DESC_COMMAND_IMPERSONATE_PROMPT_PARAM, "책의 것 대신 사용할 대필 프롬프트 (템플릿). 비워 두면 책의 것");
        setValue(L.DESC_COMMAND_GENERATE_ANNOTATION, "모델이 이야기의 파트를 검토하게 하고 발견한 내용을 주석으로 추가합니다. 토큰이 듭니다.");
        setValue(L.DESC_COMMAND_GENERATE_ANNOTATION_LLM, "모델이 파트 `part`(핸들. 마지막 파트뿐 아니라 어느 파트든)를 AI로 주석 달기 대화 상자처럼 검토하게 합니다: 파트, 그 앞의 이야기(오래된 이야기는 요약)와 뒤의 이야기, 책의 로어와 문체, 파트에 이미 있는 메모를 읽고 연속성 오류, 로어와의 모순, 약한 구절, 문체의 실수를 찾습니다. 각 발견 사항은 모델이 인용한 구절(인용문이 텍스트에 없으면 파트 전체)에 대한 주석(출처 AI)이 되어 즉시 추가됩니다. 이야기의 텍스트는 변경되지 않습니다. `profile`은 실행의 모델 대신 검토에 사용할 에이전트의 모델 프로필입니다. 느리며 토큰이 듭니다. 파트의 핸들과 새 주석을 반환합니다 (동의하지 않는 것에는 resolve-annotation, update-annotation 또는 delete-annotation을 사용하세요).");
        setValue(L.DESC_COMMAND_GENERATE_ANNOTATION_RETURN, "JSON 객체: 파트의 핸들, 생성된 주석 수, 주석");
