        setValue(L.DESC_COMMAND_SET_BOOK_HISTORY_LIMIT, "책의 기록이 각 파트에 대해 보관하는 버전 수를 설정하거나 책의 제한을 없앱니다. 매개변수: maxVersions.");
        setValue(L.DESC_COMMAND_SET_BOOK_HISTORY_LIMIT_LLM, "이 책의 버전 기록이 한 파트에 대해 보관하는 최대 버전 수를 설정합니다 (0은 지금부터 기록을 보관하지 않으며, 이미 있는 버전은 유지됨). maxVersions가 없으면 책의 제한을 없앱니다. 폴더, 사용자, 관리자의 제한은 계속 적용되고 가장 엄격한 것이 우선하므로 책이 이를 높일 수 없습니다. 책을 변경하며 버전은 삭제하지 않습니다.");
        setValue(L.DESC_COMMAND_SET_BOOK_HISTORY_LIMIT_RETURN, "bookLimit(이 책의 제한, 없으면 null), effectiveLimit(적용되는 제한, 없으면 null), setBy(BOOK, FOLDER, USER, PERMISSION 또는 NONE)를 담은 JSON");
        setValue(L.DESC_COMMAND_HISTORY_MAX_VERSIONS_PARAM, "보관할 파트당 최대 버전 수. 0은 기록을 보관하지 않음. 생략하면 책의 제한을 없앰");
        setValue(L.DESC_COMMAND_GET_BOOK_STATISTICS, "열려 있는 책에 한 작업을 날짜별로 보여 줍니다.");
        setValue(L.DESC_COMMAND_GET_BOOK_STATISTICS_LLM, "날짜 범위에서 책에 한 작업을 날짜별로: 전송 및 생성된 토큰, 작성/생성/삭제된 단어, 생성 및 삭제된 파트, 편집, 책을 열고, 편집하고, 생성하고, 에이전트가 작업한 시간(분), 책 크기의 변화. 범위는 이름 (today, yesterday, last-7-days, last-30-days, this-month, all-time. 기본값은 last-7-days), 하루 (2026-03-14) 또는 이틀 (2026-03-01..2026-03-14)이며, 대상은 all (기본값), me 또는 agents입니다. 읽기만 합니다.");
