        setValue(L.DESC_COMMAND_GET_STATISTICS_LLM, "날짜 범위에서 작성자가 모든 책에 한 작업: 합계와 날짜별 또는 책별 줄 (날짜별이 기본값, 또는 책별. 책은 얻은 단어 수 순서로 나오며 handle, name, folder가 있고, 사라진 책도 deleted로 표시되어 포함됨). 수치는 책 하나의 경우와 같습니다: 토큰, 단어, 파트, 편집, 시간(분), 크기 증가. 범위는 이름 (today, yesterday, last-7-days, last-30-days, this-month, all-time. 기본값은 last-7-days), 하루 (2026-03-14) 또는 이틀 (2026-03-01..2026-03-14)이며, 대상은 all (기본값), me 또는 agents입니다. 책들의 시간은 겹치며, 합계가 실제 시간입니다. 읽기만 합니다.");
