        setValue(L.DESC_MACRO_EVAL, "식에 대한 true 또는 false: 비교(== != < <= > >= ~= contains has)를 and, or, not, 괄호로 연결합니다. 텍스트는 따옴표로 쓰고, 이름은 템플릿의 값(povCharacter, presentCharacters, 인수 없는 매크로)이며, .name은 로컬 변수, $name은 전역 변수입니다. 알 수 없는 이름이나 구문 오류는 Error를 반환합니다. ==는 정확히 비교하고 (숫자는 값으로), ~=는 대소문자를 무시하며, contains는 텍스트 안에서 텍스트를 찾고, has는 쉼표로 구분한 목록에서 항목을 찾습니다.");
        setValue(L.DESC_COMMAND_GET_PLANNED_SCENES, "책의 플래너에 있는 장면을 상세 정보 및 작성 여부와 함께 나열합니다.");
        setValue(L.DESC_COMMAND_GET_PLANNED_SCENES_LLM, "작성자가 쓰려고 계획한 장면을 순서대로, 번호, 제목, 장면 배경, 시점 인물, 등장인물, 지시문, 완료 여부와 함께 나열합니다. 장면을 추가하기 전에 읽어서 중복되지 않게 하세요.");
