        setValue(L.DESC_COMMAND_ADD_PLANNED_SCENE_LLM, "작성자의 플래너 끝에 장면을 추가합니다: 짧은 제목과 작성자가 쓸 때 새 턴 입력 창에 넣을 턴 상세 정보(지시문, 장면 배경, 시점 인물, 등장인물). 작성자는 플래너 탭에서 즉시 보고 편집하거나 삭제할 수 있습니다. 지시문은 이야기 모델에게 주는 구체적이고 짧은 지시로 쓰세요. 장면 자체를 쓰지 마세요.");
