        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_ACTIVATION, "항목이 키 외에 언제 사용되는지를 변경합니다. 매개변수: entry (핸들), preventRecursion, recursionOnly, activationContext, activationParts, activationSummaries, fromMessage, toMessage, condition.");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_ACTIVATION_LLM, "주어진 핸들의 항목의 활성화 설정을 이 순서로 변경합니다: preventRecursion (true: 이 항목의 단어가 다른 항목을 활성화하지 않음), recursionOnly (true: 사용된 다른 항목의 내용에서 필터가 발견될 때만 항목이 사용됨, 로어북의 스캔 깊이 참조), activationContext (INSTRUCTIONS: 필터를 턴의 지시문에서 찾음, INCLUDE_PARTS: 이야기의 최신 activationParts개 파트에서도 찾음), activationParts, activationSummaries (true: 필터를 요약에서도 찾음), fromMessage와 toMessage (항목은 해당 범위의 번호를 가진 파트를 만드는 턴에만 사용됨, 양쪽 포함, 첫 파트는 1, 0은 제한 제거), condition (내용과 같은 방식으로 작성하며 참 값을 내야 하는 템플릿, 빈 텍스트는 제거). 빈 텍스트인 매개변수는 그대로 유지되므로 뒤의 것을 바꾸려면 앞의 것을 빈 텍스트로 지정하세요 (condition만 다르며 빈 텍스트가 조건을 제거함). 현재 값은 get-lore-entry로 읽으세요. 책을 변경합니다.");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_ACTIVATION_RETURN, "변경 후 항목의 활성화 설정을 담은 JSON");
        setValue(L.DESC_COMMAND_LORE_PREVENT_RECURSION_PARAM, "true: 이 항목의 내용에 있는 단어가 다른 항목을 활성화하지 않음. false는 허용");
        setValue(L.DESC_COMMAND_LORE_ACTIVATION_CONTEXT_PARAM, "필터를 찾는 위치: INSTRUCTIONS (턴의 지시문) 또는 INCLUDE_PARTS (지시문과 이야기의 최신 파트)");
