        setValue(L.DESC_TEMPLATE_EXPORT_WRITTEN_PERCENT, "작성자가 쓴 단어의 비율(퍼센트, 정수).");
        setValue(L.DESC_TEMPLATE_EXPORT_GENERATED_PERCENT, "모델이 생성한 단어의 비율(퍼센트, 정수).");
